cat > /workspace/hclfmt.go <<'GOEOF'
package main

import (
	"strings"
)

// Token kinds produced by the HCL scanner.
type Kind uint8

const (
	KIdent Kind = iota
	KNumber
	KString  // quoted string, raw text kept
	KHeredoc // heredoc, raw text kept (may span lines)
	KComment // line or block comment
	KNewline
	// punctuation / operators
	KOParen
	KCParen
	KOBrack
	KCBrack
	KOHBrace
	KCHBrace
	KComma
	KDot
	KEllipsis
	KEqual
	KPlus
	KMinus
	KNegate
	KStar
	KSlash
	KPercent
	KEqEq
	KNeq
	KLess
	KLessEq
	KGreater
	KGreaterEq
	KAnd
	KOr
	KNot
	KQuestion
	KColon
	KArrow
	KSPPlus // "+" (always binary in HCL)
)

type Tok struct {
	Kind Kind
	Text string
	// position info (line, col) 1-based, for error reporting
	Line int
	Col  int
	End  int // end column (exclusive)
}

func (t Tok) isBracketOpen() bool {
	switch t.Kind {
	case KOParen, KOBrack, KOHBrace:
		return true
	}
	return false
}

func (t Tok) isBracketClose() bool {
	switch t.Kind {
	case KCParen, KCBrack, KCHBrace:
		return true
	}
	return false
}

// operandEnd reports whether the token terminates an expression operand, which
// makes a following "-" a binary minus rather than a negation.
func (t Tok) operandEnd() bool {
	switch t.Kind {
	case KIdent, KNumber, KString, KHeredoc, KCParen, KCBrack, KCHBrace:
		return true
	}
	return false
}

// ---------------------------------------------------------------------------
// Scanner
// ---------------------------------------------------------------------------

type scanner struct {
	src  string
	pos  int
	line int
	col  int
	toks []Tok
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}
func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-'
}
func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func (s *scanner) emit(k Kind, start int, startLine, startCol int) {
	s.toks = append(s.toks, Tok{Kind: k, Text: s.src[start:s.pos], Line: startLine, Col: startCol, End: s.col})
}

// advance consumes n characters keeping line/col tracking.
func (s *scanner) advance(n int) {
	for i := 0; i < n; i++ {
		if s.pos >= len(s.src) {
			return
		}
		if s.src[s.pos] == '\n' {
			s.line++
			s.col = 1
		} else {
			s.col++
		}
		s.pos++
	}
}

// tokenize scans the whole input.
func tokenize(src string) []Tok {
	s := &scanner{src: src, line: 1, col: 1}
	for s.pos < len(src) {
		c := src[s.pos]
		start, sl, sc := s.pos, s.line, s.col
		switch {
		case c == '\n':
			s.advance(1)
			s.emit(KNewline, start, sl, sc)
		case c == ' ' || c == '\t' || c == '\r':
			s.advance(1)
		case c == '#' || (c == '/' && s.pos+1 < len(src) && src[s.pos+1] == '/'):
			for s.pos < len(src) && src[s.pos] != '\n' {
				s.advance(1)
			}
			s.emit(KComment, start, sl, sc)
		case c == '/' && s.pos+1 < len(src) && src[s.pos+1] == '*':
			s.advance(2)
			for s.pos < len(src) {
				if src[s.pos] == '*' && s.pos+1 < len(src) && src[s.pos+1] == '/' {
					s.advance(2)
					break
				}
				s.advance(1)
			}
			s.emit(KComment, start, sl, sc)
		case c == '"':
			tok := scanString(s)
			s.toks = append(s.toks, tok)
		case c == '<' && s.pos+1 < len(src) && src[s.pos+1] == '<':
			if hd, ok := scanHeredoc(s); ok {
				s.toks = append(s.toks, hd)
			} else {
				s.advance(1)
				s.emit(KLess, start, sl, sc)
			}
		case isIdentStart(c):
			for s.pos < len(src) && isIdentChar(src[s.pos]) {
				s.advance(1)
			}
			s.emit(KIdent, start, sl, sc)
		case isDigit(c):
			for s.pos < len(src) && isDigit(src[s.pos]) {
				s.advance(1)
			}
			// fraction
			if s.pos < len(src) && src[s.pos] == '.' {
				save := s.pos
				saveLine, saveCol := s.line, s.col
				s.advance(1)
				if s.pos < len(src) && isDigit(src[s.pos]) {
					for s.pos < len(src) && isDigit(src[s.pos]) {
						s.advance(1)
					}
				} else {
					// not a fraction, back off
					s.pos, s.line, s.col = save, saveLine, saveCol
				}
			}
			// exponent
			if s.pos < len(src) && (src[s.pos] == 'e' || src[s.pos] == 'E') {
				save, saveLine, saveCol := s.pos, s.line, s.col
				s.advance(1)
				if s.pos < len(src) && (src[s.pos] == '+' || src[s.pos] == '-') {
					s.advance(1)
				}
				if s.pos < len(src) && isDigit(src[s.pos]) {
					for s.pos < len(src) && isDigit(src[s.pos]) {
						s.advance(1)
					}
				} else {
					s.pos, s.line, s.col = save, saveLine, saveCol
				}
			}
			s.emit(KNumber, start, sl, sc)
		default:
			one, two := "", ""
			if s.pos+1 < len(src) {
				two = src[s.pos : s.pos+2]
			}
			switch two {
			case "==":
				s.advance(2)
				s.emit(KEqEq, start, sl, sc)
				continue
			case "!=":
				s.advance(2)
				s.emit(KNeq, start, sl, sc)
				continue
			case "<=":
				s.advance(2)
				s.emit(KLessEq, start, sl, sc)
				continue
			case ">=":
				s.advance(2)
				s.emit(KGreaterEq, start, sl, sc)
				continue
			case "&&":
				s.advance(2)
				s.emit(KAnd, start, sl, sc)
				continue
			case "||":
				s.advance(2)
				s.emit(KOr, start, sl, sc)
				continue
			case "=>":
				s.advance(2)
				s.emit(KArrow, start, sl, sc)
				continue
			case "..":
				s.advance(2)
				s.emit(KEllipsis, start, sl, sc)
				continue
			}
			var k Kind
			switch c {
			case '(':
				k = KOParen
			case ')':
				k = KCParen
			case '[':
				k = KOBrack
			case ']':
				k = KCBrack
			case '{':
				k = KOHBrace
			case '}':
				k = KCHBrace
			case ',':
				k = KComma
			case '.':
				k = KDot
			case '=':
				k = KEqual
			case '+':
				k = KSPPlus
			case '-':
				k = KMinus // upgraded to KNegate later
			case '*':
				k = KStar
			case '/':
				k = KSlash
			case '%':
				k = KPercent
			case '<':
				k = KLess
			case '>':
				k = KGreater
			case '!':
				k = KNot
			case '?':
				k = KQuestion
			case ':':
				k = KColon
			default:
				// unknown char: emit as a single-char ident-ish token so that
				// formatting keeps it on its own
				s.advance(1)
				s.emit(KIdent, start, sl, sc)
				continue
			}
			s.advance(1)
			s.emit(k, start, sl, sc)
		}
	}
	// decide negate vs minus
	for i := range s.toks {
		if s.toks[i].Kind == KMinus {
			if i == 0 || !s.toks[i-1].operandEnd() {
				s.toks[i].Kind = KNegate
			}
		}
	}
	return s.toks
}

// scanString scans a quoted string (including template interpolation) and
// returns it as a single KString token.
func scanString(s *scanner) Tok {
	start, sl, sc := s.pos, s.line, s.col
	s.advance(1) // opening quote
	for s.pos < len(s.src) {
		c := s.src[s.pos]
		if c == '\\' {
			s.advance(2)
			continue
		}
		if c == '"' {
			s.advance(1)
			break
		}
		if c == '$' && s.pos+1 < len(s.src) && s.src[s.pos+1] == '{' {
			// interpolation: skip balanced braces
			s.advance(2)
			depth := 1
			for s.pos < len(s.src) && depth > 0 {
				switch s.src[s.pos] {
				case '{':
					depth++
				case '}':
					depth--
				case '"':
					// nested string: skip it
					sub := scanString(s)
					_ = sub
					continue
				}
				s.advance(1)
			}
			continue
		}
		if c == '\n' {
			// unterminated string: stop at newline
			break
		}
		s.advance(1)
	}
	return Tok{Kind: KString, Text: s.src[start:s.pos], Line: sl, Col: sc, End: s.col}
}

// scanHeredoc scans "<<IDENT\n ... \nIDENT". Returns ok=false when the input
// does not look like a heredoc introduction.
func scanHeredoc(s *scanner) (Tok, bool) {
	start, sl, sc := s.pos, s.line, s.col
	p := s.pos
	if p+2 >= len(s.src) {
		return Tok{}, false
	}
	p += 2
	indented := false
	if p < len(s.src) && s.src[p] == '-' {
		indented = true
		p++
	}
	q := p
	for q < len(s.src) && isIdentChar(s.src[q]) {
		q++
	}
	if q == p {
		return Tok{}, false
	}
	marker := s.src[p:q]
	// must be followed by a newline (possibly with trailing spaces)
	r := q
	for r < len(s.src) && (s.src[r] == ' ' || s.src[r] == '\t' || s.src[r] == '\r') {
		r++
	}
	if r >= len(s.src) || s.src[r] != '\n' {
		return Tok{}, false
