// formatTemplate re-emits a string or heredoc literal with the interpolations
// and template directives formatted canonically.
func formatTemplate(text string, heredoc bool) string {
	var sb strings.Builder
	i := 0
	for i < len(text) {
		c := text[i]
		if (c == '$' || c == '%') && i+1 < len(text) && text[i+1] == '{' {
			depth := 1
			j := i + 2
			for j < len(text) && depth > 0 {
				switch text[j] {
				case '{':
					depth++
				case '}':
					depth--
				case '"':
					j = scanStringAt(text, j)
					continue
				}
				j++
			}
			closed := j < len(text)
