	indent      int
	assign      int  // index of the assign token, -1 when absent
	participate bool // whether the line takes part in "=" alignment
	leadWidth   int  // rendered width of the tokens before the assign
	padWidth    int
}

// formatHCL formats the given HCL source the way hclwrite does.
func formatHCL(src string) string {
	toks := tokenize(src)

	var lines []*hclLine
	cur := &hclLine{assign: -1}
	nest := 0
	nestAssign := 0
	for _, t := range toks {
		if t.Kind == KNewline {
			lines = append(lines, cur)
			cur = &hclLine{assign: -1}
			continue
		}
		if cur.assign < 0 && t.Kind == KEqual {
			cur.assign = len(cur.toks)
			nestAssign = nest
		}
		cur.toks = append(cur.toks, t)
		if t.isBracketOpen() {
			nest++
		} else if t.isBracketClose() {
			nest--
		}
	}
	if len(cur.toks) > 0 {
		lines = append(lines, cur)
	}

	for _, l := range lines {
		if len(l.toks) == 0 {
			continue
		}
		closings := 0
		for _, t := range l.toks {
			if t.isBracketClose() {
				closings++
			}
		}
