		l.indent = nestStart - closings
		if l.indent < 0 {
			l.indent = 0
		}
		if l.assign >= 0 {
			l.leadWidth = renderedWidth(l.toks[:l.assign])
			l.participate = nestAssign == nestEndOf(l)
		}
