		if !lines[i].participate {
			continue
		}
		target := lines[i].leadWidth + 1
		j := i + 1
		for j < len(lines) && lines[j].participate {
			if lines[j].leadWidth+1 > target {
				target = lines[j].leadWidth + 1
			}
			j++
		}
		for k := i; k < j; k++ {
			lines[k].padWidth = target - lines[k].leadWidth
		}
		i = j - 1
	}

