	for idx, l := range lines {
		last := idx == len(lines)-1
		if len(l.toks) == 0 {
			if !last {
				sb.WriteByte('\n')
			}
			continue
		}
		for k := 0; k < l.indent*2; k++ {
			sb.WriteByte(' ')
		}
		if l.assign >= 0 {
			sb.WriteString(renderTokens(l.toks[:l.assign]))
			for k := 0; k < l.padWidth; k++ {
				sb.WriteByte(' ')
			}
