			sb.WriteString(renderTokens(l.toks[l.assign+1:]))
		} else {
			sb.WriteString(renderTokens(l.toks))
		}
		if !last {
			sb.WriteByte('\n')
		}
	}
	return sb.String()
}

// nestAtStart computes the nesting level at the beginning of line li.
func nestAtStart(li *hclLine, lines []*hclLine) int {
	// find the index of li
	nest := 0
	for _, l := range lines {
		if l == li {
			return nest
		}
		for _, t := range l.toks {
			if t.isBracketOpen() {
				nest++
			} else if t.isBracketClose() {
				nest--
			}
		}
	}
	return nest
}

func nestEndOf(l *hclLine) int {
	nest := 0
	for _, t := range l.toks {
		if t.isBracketOpen() {
			nest++
		} else if t.isBracketClose() {
			nest--
		}
	}
	return nest
}

func renderedWidth(toks []Tok) int {
	w := 0
	for i, t := range toks {
		if i > 0 && spaceBetween(toks[i-1], t) {
			w++
		}
		w += len(renderToken(t))
	}
	return w
}
