cat > /workspace/hclfmt.go <<'GOEOF'
package main

import (
	"strings"
)

// Token kinds produced by the HCL scanner.
type Kind uint8

const (
	KIdent Kind = iota
	KNumber
	KString  // quoted string, raw text kept
	KHeredoc // heredoc, raw text kept (may span lines)
	KComment // line or block comment
	KNewline
	// punctuation / operators
	KOParen
	KCParen
	KOBrack
	KCBrack
	KOHBrace
	KCHBrace
	KComma
	KDot
	KEllipsis
	KEqual
	KPlus
	KMinus
	KNegate
	KStar
	KSlash
	KPercent
	KEqEq
	KNeq
	KLess
	KLessEq
	KGreater
	KGreaterEq
	KAnd
	KOr
	KNot
	KQuestion
	KColon
	KArrow
)

type Tok struct {
	Kind Kind
	Text string
	Line int
	Col  int
	End  int
}

func (t Tok) isBracketOpen() bool {
	switch t.Kind {
	case KOParen, KOBrack, KOHBrace:
		return true
	}
	return false
}

func (t Tok) isBracketClose() bool {
	switch t.Kind {
	case KCParen, KCBrack, KCHBrace:
		return true
	}
	return false
}

// operandEnd reports whether the token terminates an expression operand, which
// makes a following "-" a binary minus rather than a negation.
func (t Tok) operandEnd() bool {
	switch t.Kind {
	case KIdent, KNumber, KString, KHeredoc, KCParen, KCBrack, KCHBrace:
		return true
	}
	return false
}

// ---------------------------------------------------------------------------
// Scanner
// ---------------------------------------------------------------------------

type scanner struct {
	src  string
	pos  int
	line int
	col  int
	toks []Tok
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}
func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-'
}
func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func (s *scanner) emit(k Kind, start int, startLine, startCol int) {
	s.toks = append(s.toks, Tok{Kind: k, Text: s.src[start:s.pos], Line: startLine, Col: startCol, End: s.col})
}

func (s *scanner) advance(n int) {
	for i := 0; i < n; i++ {
		if s.pos >= len(s.src) {
			return
		}
		if s.src[s.pos] == '\n' {
			s.line++
			s.col = 1
