			one, two := "", ""
			if s.pos+1 < len(src) {
				two = src[s.pos : s.pos+2]
			}
			_ = one
			var k Kind
			handled := true
			switch two {
			case "==":
				k = KEqEq
			case "!=":
				k = KNeq
			case "<=":
				k = KLessEq
			case ">=":
				k = KGreaterEq
			case "&&":
