				if src[s.pos] == '*' && s.pos+1 < len(src) && src[s.pos+1] == '/' {
					s.advance(2)
					break
				}
				s.advance(1)
			}
			s.emit(KComment, start, sl, sc)
		case c == '"':
			s.toks = append(s.toks, scanStringTok(s))
		case c == '<' && s.pos+1 < len(src) && src[s.pos+1] == '<':
			if hd, ok := scanHeredoc(s); ok {
				s.toks = append(s.toks, hd)
			} else {
				s.advance(1)
				s.emit(KLess, start, sl, sc)
			}
		case isIdentStart(c):
			for s.pos < len(src) && isIdentChar(src[s.pos]) {
				s.advance(1)
			}
			s.emit(KIdent, start, sl, sc)
		case isDigit(c):
			scanNumber(s)
			s.emit(KNumber, start, sl, sc)
		default:
			one, two := "", ""
			if s.pos+1 < len(src) {
				two = src[s.pos : s.pos+2]
			}
			_ = one
			var k Kind
			handled := true
			switch two {
			case "==":
				k = KEqEq
			case "!=":
				k = KNeq
			case "<=":
				k = KLessEq
			case ">=":
				k = KGreaterEq
			case "&&":
				k = KAnd
			case "||":
				k = KOr
			case "=>":
				k = KArrow
			case "..":
				k = KEllipsis
			default:
				handled = false
			}
			if handled {
				s.advance(2)
				s.emit(k, start, sl, sc)
				continue
			}
			switch c {
			case '(':
				k = KOParen
			case ')':
				k = KCParen
			case '[':
				k = KOBrack
			case ']':
				k = KCBrack
			case '{':
				k = KOHBrace
			case '}':
				k = KCHBrace
			case ',':
				k = KComma
			case '.':
				k = KDot
			case '=':
				k = KEqual
			case '+':
				k = KPlus
			case '-':
				k = KMinus
			case '*':
				k = KStar
			case '/':
				k = KSlash
			case '%':
				k = KPercent
			case '<':
				k = KLess
			case '>':
				k = KGreater
			case '!':
				k = KNot
			case '?':
				k = KQuestion
			case ':':
				k = KColon
			default:
				s.advance(1)
				s.emit(KIdent, start, sl, sc)
				continue
			}
			s.advance(1)
			s.emit(k, start, sl, sc)
		}
	}
	for i := range s.toks {
		if s.toks[i].Kind == KMinus {
			if i == 0 || !s.toks[i-1].operandEnd() {
				s.toks[i].Kind = KNegate
			}
		}
	}
	return s.toks
}

func scanNumber(s *scanner) {
	for s.pos < len(s.src) && isDigit(s.src[s.pos]) {
		s.advance(1)
	}
	if s.pos < len(s.src) && s.src[s.pos] == '.' {
		save, sl, sc := s.pos, s.line, s.col
		s.advance(1)
		if s.pos < len(s.src) && isDigit(s.src[s.pos]) {
			for s.pos < len(s.src) && isDigit(s.src[s.pos]) {
				s.advance(1)
			}
		} else {
			s.pos, s.line, s.col = save, sl, sc
		}
	}
	if s.pos < len(s.src) && (s.src[s.pos] == 'e' || s.src[s.pos] == 'E') {
		save, sl, sc := s.pos, s.line, s.col
		s.advance(1)
		if s.pos < len(s.src) && (s.src[s.pos] == '+' || s.src[s.pos] == '-') {
			s.advance(1)
		}
		if s.pos < len(s.src) && isDigit(s.src[s.pos]) {
			for s.pos < len(s.src) && isDigit(s.src[s.pos]) {
				s.advance(1)
			}
		} else {
			s.pos, s.line, s.col = save, sl, sc
		}
	}
}

// scanStringTok scans a quoted string (including interpolation) as one token.
func scanStringTok(s *scanner) Tok {
	start, sl, sc := s.pos, s.line, s.col
	s.advance(1)
	for s.pos < len(s.src) {
		c := s.src[s.pos]
		if c == '\\' {
			s.advance(2)
			continue
		}
		if c == '"' {
			s.advance(1)
			break
		}
		if (c == '$' || c == '%') && s.pos+1 < len(s.src) && s.src[s.pos+1] == '{' {
			s.advance(2)
			depth := 1
			for s.pos < len(s.src) && depth > 0 {
				switch s.src[s.pos] {
				case '{':
					depth++
				case '}':
					depth--
				case '"':
					scanStringTok(s)
					continue
				}
				s.advance(1)
			}
			continue
		}
		if c == '\n' {
			break
		}
		s.advance(1)
	}
	return Tok{Kind: KString, Text: s.src[start:s.pos], Line: sl, Col: sc, End: s.col}
}

// scanHeredoc scans "<<IDENT\n...\nIDENT".
func scanHeredoc(s *scanner) (Tok, bool) {
	start, sl, sc := s.pos, s.line, s.col
	p := s.pos
	if p+2 >= len(s.src) {
		return Tok{}, false
	}
	p += 2
	indented := false
	if p < len(s.src) && s.src[p] == '-' {
		indented = true
		p++
	}
	q := p
	for q < len(s.src) && isIdentChar(s.src[q]) {
		q++
	}
	if q == p {
		return Tok{}, false
	}
	marker := s.src[p:q]
	r := q
	for r < len(s.src) && (s.src[r] == ' ' || s.src[r] == '\t' || s.src[r] == '\r') {
		r++
	}
	if r >= len(s.src) || s.src[r] != '\n' {
		return Tok{}, false
	}
	i := r + 1
	for {
		lineEnd := i
		for lineEnd < len(s.src) && s.src[lineEnd] != '\n' {
			lineEnd++
		}
		lineText := s.src[i:lineEnd]
		trimmed := strings.TrimRight(lineText, " \t\r")
		if indented {
			trimmed = strings.TrimLeft(trimmed, " \t")
		}
		if trimmed == marker {
			return Tok{Kind: KHeredoc, Text: s.src[start:lineEnd], Line: sl, Col: sc, End: s.col}, true
		}
		if lineEnd >= len(s.src) {
			return Tok{Kind: KHeredoc, Text: s.src[start:len(s.src)], Line: sl, Col: sc, End: s.col}, true
		}
		i = lineEnd + 1
	}
}
