{"command": "cd /workspace && cat > hclwrite.go <<'GOEOF'
package main

import (
	"strings"
)

// spaceBetween reports whether a single space must be printed between the two
// given tokens.
func spaceBetween(a, b Tok) bool {
	switch {
	case a.Kind == KNegate:
		return false
	case a.Kind == KOHBrace && b.Kind == KCHBrace:
		return false
	case a.Kind == KOHBrace:
		return true
	case b.Kind == KCHBrace:
		return true
	case a.Kind == KOParen || a.Kind == KOBrack:
		return false
	case b.Kind == KCParen || b.Kind == KCBrack:
		return a.Kind == KComma
	case a.Kind == KComma:
		return true
	case a.Kind == KDot || b.Kind == KDot:
		return false
	case b.Kind == KOParen:
		return a.Kind != KIdent
	case b.Kind == KOBrack:
		return a.Kind == KString
	case b.Kind == KNegate:
		return true
	}
	return true
}

// renderTokens renders a token sequence on a single line using the canonical
// spacing rules.
func renderTokens(toks []Tok) string {
	var sb strings.Builder
	for i, t := range toks {
		if i > 0 && spaceBetween(toks[i-1], t) {
			sb.WriteByte(' ')
		}
		sb.WriteString(renderToken(t))
	}
	return sb.String()
}

func renderToken(t Tok) string {
	switch t.Kind {
	case KString:
		return formatTemplate(t.Text, false)
	case KHeredoc:
		return formatTemplate(t.Text, true)
	}
	return t.Text
}

// formatTemplate re-emits a string or heredoc literal with the interpolations
// and template directives formatted canonically.
func formatTemplate(text string, heredoc bool) string {
	var sb strings.Builder
	i := 0
	for i < len(text) {
		c := text[i]
		if (c == '$' || c == '%') && i+1 < len(text) && text[i+1] == '{' {
			depth := 1
			j := i + 2
			for j < len(text) && depth > 0 {
				switch text[j] {
				case '{':
					depth++
				case '}':
					depth--
				case '"':
					j = scanStringAt(text, j)
					continue
				}
				j++
			}
			closed := j < len(text)
			inner := text[i+2 : j]
			sb.WriteByte(c)
			sb.WriteByte('{')
			if strings.TrimSpace(inner) != "" {
				sb.WriteString(renderTokens(tokenize(inner)))
			}
			if closed {
				sb.WriteByte('}')
			}
			i = j
			if closed {
				i++
			}
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String()
}

