	case boolValue:
		return f.DefValue == "false"
	case durationValue:
		return f.DefValue == "0" || f.DefValue == "0s"
	case uintValue:
		return f.DefValue == "0"
	case stringValue:
		return f.DefValue == ""
	default:
		return f.DefValue == "[]" || f.DefValue == ""
	}
}

