cat > /workspace/cli.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

// ---------------------------------------------------------------------------
// Values
// ---------------------------------------------------------------------------

type Value interface {
	String() string
	Set(string) error
	Type() string
}

type stringValue struct{ p *string }

func (s stringValue) String() string     { return *s.p }
func (s stringValue) Set(v string) error { *s.p = v; return nil }
func (s stringValue) Type() string       { return "string" }

type boolValue struct{ p *bool }

func (b boolValue) String() string { return strconv.FormatBool(*b.p) }
func (b boolValue) Set(v string) error {
	x, err := strconv.ParseBool(v)
	if err != nil {
		return fmt.Errorf("strconv.ParseBool: parsing %q: invalid syntax", v)
	}
	*b.p = x
	return nil
}
func (b boolValue) Type() string { return "bool" }

type durationValue struct{ p *time.Duration }

func (d durationValue) String() string { return (*d.p).String() }
func (d durationValue) Set(v string) error {
	x, err := time.ParseDuration(v)
	if err != nil {
		return fmt.Errorf("time: invalid duration %q", v)
	}
	*d.p = x
	return nil
}
func (d durationValue) Type() string { return "duration" }

type uintValue struct{ p *uint }

func (u uintValue) String() string { return strconv.FormatUint(uint64(*u.p), 10) }
func (u uintValue) Set(v string) error {
	x, err := strconv.ParseUint(v, 10, 64)
	if err != nil {
		return fmt.Errorf("strconv.ParseUint: parsing %q: invalid syntax", v)
	}
	*u.p = uint(x)
	return nil
}
func (u uintValue) Type() string { return "uint" }

type stringArrayValue struct {
	p       *[]string
	typeStr string
}

func (s stringArrayValue) String() string { return "[" + strings.Join(*s.p, ",") + "]" }
func (s stringArrayValue) Set(v string) error {
	*s.p = append(*s.p, v)
	return nil
}
func (s stringArrayValue) Type() string { return s.typeStr }

// varValue is the value type used for --var, whose type name shows up in the
// help output.
type varValue struct{ p *[]string }

func (v varValue) String() string { return "[" + strings.Join(*v.p, ",") + "]" }
func (v varValue) Set(s string) error {
	kv := strings.SplitN(s, "=", 2)
	if len(kv) != 2 {
		return fmt.Errorf("variables must be format as key=value, got: %q", s)
	}
	*v.p = append(*v.p, s)
	return nil
}
func (v varValue) Type() string { return "<name>=<value>" }

// ---------------------------------------------------------------------------
// Flags
// ---------------------------------------------------------------------------

type Flag struct {
	Name        string
	Shorthand   string
	Usage       string
	Value       Value
	DefValue    string
	NoOptDefVal string
	Changed     bool
	Hidden      bool
	Required    bool
}

type FlagSet struct {
	flags   []*Flag
	byName  map[string]*Flag
	byShort map[string]*Flag
	args    []string
}

func NewFlagSet() *FlagSet {
	return &FlagSet{byName: map[string]*Flag{}, byShort: map[string]*Flag{}}
}

func (fs *FlagSet) add(f *Flag) {
	if _, ok := fs.byName[f.Name]; ok {
		return
	}
	fs.flags = append(fs.flags, f)
	fs.byName[f.Name] = f
	if f.Shorthand != "" {
		fs.byShort[f.Shorthand] = f
	}
}

func (fs *FlagSet) Lookup(name string) *Flag { return fs.byName[name] }

func (fs *FlagSet) StringVarP(p *string, name, short, def, usage string) {
	*p = def
	fs.add(&Flag{Name: name, Shorthand: short, Usage: usage, Value: stringValue{p}, DefValue: def})
}
func (fs *FlagSet) StringVar(p *string, name, def, usage string) {
	fs.StringVarP(p, name, "", def, usage)
}
func (fs *FlagSet) BoolVar(p *bool, name string, def bool, usage string) {
	*p = def
	f := &Flag{Name: name, Usage: usage, Value: boolValue{p}, DefValue: strconv.FormatBool(def), NoOptDefVal: "true"}
	fs.add(f)
}
func (fs *FlagSet) BoolVarP(p *bool, name, short string, def bool, usage string) {
	*p = def
	f := &Flag{Name: name, Shorthand: short, Usage: usage, Value: boolValue{p}, DefValue: strconv.FormatBool(def), NoOptDefVal: "true"}
	fs.add(f)
}
func (fs *FlagSet) DurationVar(p *time.Duration, name string, def time.Duration, usage string) {
	*p = def
	fs.add(&Flag{Name: name, Usage: usage, Value: durationValue{p}, DefValue: def.String()})
}
func (fs *FlagSet) UintVar(p *uint, name string, def uint, usage string) {
	*p = def
	fs.add(&Flag{Name: name, Usage: usage, Value: uintValue{p}, DefValue: strconv.FormatUint(uint64(def), 10)})
}
func (fs *FlagSet) StringsVar(p *[]string, name string, def []string, usage string) {
	*p = def
	fs.add(&Flag{Name: name, Usage: usage, Value: stringArrayValue{p, "strings"}, DefValue: "[" + strings.Join(def, ",") + "]"})
}
func (fs *FlagSet) VarVar(p *[]string, name string, def []string, usage string) {
	*p = def
	fs.add(&Flag{Name: name, Usage: usage, Value: varValue{p}, DefValue: "[" + strings.Join(def, ",") + "]"})
}

func (fs *FlagSet) MarkHidden(name string) {
	if f := fs.byName[name]; f != nil {
		f.Hidden = true
	}
}
func (fs *FlagSet) MarkRequired(name string) {
	if f := fs.byName[name]; f != nil {
		f.Required = true
	}
}

// unquoteUsage mirrors pflag.UnquoteUsage.
func unquoteUsage(f *Flag) (name string, usage string) {
	usage = f.Usage
	for i := 0; i < len(usage); i++ {
		if usage[i] == '`' {
			for j := i + 1; j < len(usage); j++ {
				if usage[j] == '`' {
					name = usage[i+1 : j]
					usage = usage[:i] + name + usage[j+1:]
					return name, usage
				}
			}
			break
		}
	}
	name = f.Value.Type()
	switch name {
	case "bool":
		name = ""
	case "float64":
		name = "float"
	case "int64":
		name = "int"
	case "uint64":
		name = "uint"
	}
	return name, usage
}

func (f *Flag) defaultIsZeroValue() bool {
	switch f.Value.(type) {
	case boolValue:
		return f.DefValue == "false"
	case durationValue:
		return f.DefValue == "0" || f.DefValue == "0s"
	case uintValue:
		return f.DefValue == "0"
	case stringValue:
		return f.DefValue == ""
	default:
		return f.DefValue == "[]" || f.DefValue == ""
	}
}

// FlagUsages renders the flag help the way pflag does.
func (fs *FlagSet) FlagUsages() string {
	sorted := make([]*Flag, len(fs.flags))
	copy(sorted, fs.flags)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })
	var lines []string
	maxlen := 0
	for _, f := range sorted {
		if f.Hidden {
			continue
		}
		line := ""
		if f.Shorthand != "" {
			line = fmt.Sprintf("  -%s, --%s", f.Shorthand, f.Name)
		} else {
			line = fmt.Sprintf("      --%s", f.Name)
		}
		varname, usage := unquoteUsage(f)
		if varname != "" {
			line += " " + varname
		}
		if f.NoOptDefVal != "" {
			switch f.Value.Type() {
			case "string":
				line += fmt.Sprintf("[=\"%s\"]", f.NoOptDefVal)
			case "bool":
				if f.NoOptDefVal != "true" {
					line += fmt.Sprintf("[=%s]", f.NoOptDefVal)
				}
			default:
				line += fmt.Sprintf("[=%s]", f.NoOptDefVal)
			}
		}
		line += "\x00"
		if len(line) > maxlen {
			maxlen = len(line)
		}
		line += usage
		if !f.defaultIsZeroValue() {
			if f.Value.Type() == "string" {
				line += fmt.Sprintf(" (default %q)", f.DefValue)
			} else {
				line += fmt.Sprintf(" (default %s)", f.DefValue)
			}
		}
		lines = append(lines, line)
	}
	var sb strings.Builder
	for _, line := range lines {
		sidx := strings.Index(line, "\x00")
		spacing := strings.Repeat(" ", maxlen-sidx)
		sb.WriteString(line[:sidx] + " " + spacing + " " + line[sidx+1:] + "\n")
	}
	return sb.String()
}

// parse parses the given arguments, mirroring pflag's interspersed parsing.
func (fs *FlagSet) parse(args []string) error {
	fs.args = nil
	for len(args) > 0 {
		a := args[0]
		args = args[1:]
		if a == "--" {
			fs.args = append(fs.args, args...)
			break
		}
		if strings.HasPrefix(a, "--") {
			body := a[2:]
			name := body
			val := ""
			hasVal := false
			if i := strings.Index(body, "="); i >= 0 {
				name, val, hasVal = body[:i], body[i+1:], true
			}
			f := fs.byName[name]
			if f == nil {
				return fmt.Errorf("unknown flag: --%s", name)
			}
			if !hasVal {
				if f.NoOptDefVal != "" {
					val = f.NoOptDefVal
				} else if len(args) > 0 {
					val = args[0]
					args = args[1:]
				} else {
					return fmt.Errorf("flag needs an argument: --%s", name)
				}
			}
			if err := f.Value.Set(val); err != nil {
				return fmt.Errorf("invalid argument %q for %q flag: %v", val, "--"+name, err)
			}
			f.Changed = true
			continue
		}
		if len(a) > 1 && a[0] == '-' {
			shorts := a[1:]
			for len(shorts) > 0 {
				c := string(shorts[0])
				f := fs.byShort[c]
				if f == nil {
					return fmt.Errorf("unknown shorthand flag: %q in -%s", c, shorts)
				}
				shorts = shorts[1:]
				switch {
				case len(shorts) > 1 && shorts[0] == '=':
					val := shorts[1:]
					shorts = ""
					if err := f.Value.Set(val); err != nil {
						return fmt.Errorf("invalid argument %q for %q flag: %v", val, "-"+c, err)
					}
					f.Changed = true
				case f.NoOptDefVal != "":
					if err := f.Value.Set(f.NoOptDefVal); err != nil {
						return fmt.Errorf("invalid argument %q for %q flag: %v", f.NoOptDefVal, "-"+c, err)
					}
					f.Changed = true
				case len(shorts) > 0:
					val := shorts
					shorts = ""
					if err := f.Value.Set(val); err != nil {
						return fmt.Errorf("invalid argument %q for %q flag: %v", val, "-"+c, err)
					}
					f.Changed = true
				case len(args) > 0:
					val := args[0]
					args = args[1:]
					if err := f.Value.Set(val); err != nil {
						return fmt.Errorf("invalid argument %q for %q flag: %v", val, "-"+c, err)
					}
					f.Changed = true
				default:
					return fmt.Errorf("flag needs an argument: %q in -%s", c, c)
				}
			}
			continue
		}
		fs.args = append(fs.args, a)
	}
	return nil
}

// ---------------------------------------------------------------------------
// Commands
// ---------------------------------------------------------------------------

type Command struct {
	Use          string
	Short        string
	Long         string
	Example      string
	Args         func(c *Command, args []string) error
	RunE         func(c *Command, args []string) error
	Hidden       bool
	Parent       *Command
	children     []*Command
	Flags        *FlagSet
	Persistent   *FlagSet
	SilenceUsage bool
	helpFlag     *Flag
}

func (c *Command) Name() string {
	name := c.Use
	if i := strings.Index(name, " "); i >= 0 {
		name = name[:i]
	}
	return name
}

func (c *Command) AddCommand(cmds ...*Command) {
	for _, sub := range cmds {
		sub.Parent = c
		c.children = append(c.children, sub)
	}
}

func (c *Command) CommandPath() string {
	if c.Parent != nil {
		return c.Parent.CommandPath() + " " + c.Name()
	}
	return c.Name()
}

func (c *Command) UseLine() string {
	var useline string
	if c.Parent != nil {
		useline = c.Parent.CommandPath() + " " + c.Use
	} else {
		useline = c.Use
	}
	if c.hasAvailableFlags() && !strings.Contains(useline, "[flags]") {
		useline += " [flags]"
	}
	return useline
}

func (c *Command) Runnable() bool { return c.RunE != nil }

func (c *Command) hasSubCommands() bool {
	for _, sub := range c.children {
		if !sub.Hidden {
			return true
		}
	}
	return false
}

func (c *Command) hasAvailableFlags() bool {
	return len(c.localFlags().flags) > 0
}

func (c *Command) namePadding() int {
	maxLen := 11
	for _, sub := range c.children {
		if sub.Hidden {
			continue
		}
		if len(sub.Name()) > maxLen {
			maxLen = len(sub.Name())
		}
	}
	return maxLen
}

// localFlags returns the flags local to this command (including its own
// persistent flags and the implicit help flag).
func (c *Command) localFlags() *FlagSet {
	fs := NewFlagSet()
	if c.Flags != nil {
		for _, f := range c.Flags.flags {
			fs.add(f)
		}
	}
	if c.Persistent != nil {
		for _, f := range c.Persistent.flags {
			fs.add(f)
		}
	}
	if c.helpFlag != nil {
		fs.add(c.helpFlag)
	}
	return fs
}

// inheritedFlags returns the persistent flags of all parents.
func (c *Command) inheritedFlags() *FlagSet {
	fs := NewFlagSet()
	for p := c.Parent; p != nil; p = p.Parent {
		if p.Persistent != nil {
			for _, f := range p.Persistent.flags {
				fs.add(f)
			}
		}
	}
	return fs
}

func (c *Command) allFlags() *FlagSet {
	fs := NewFlagSet()
	for _, f := range c.localFlags().flags {
		fs.add(f)
	}
	for _, f := range c.inheritedFlags().flags {
		fs.add(f)
	}
	return fs
}

func (c *Command) initHelpFlag() {
	if c.helpFlag != nil {
		return
	}
	var b bool
	name := c.Name()
	if name == "" {
		name = "atlas"
	}
	c.helpFlag = &Flag{Name: "help", Shorthand: "h", Usage: "help for " + name,
		Value: boolValue{&b}, DefValue: "false", NoOptDefVal: "true"}
}

func (c *Command) UsageString() string {
	var sb strings.Builder
	sb.WriteString("Usage:")
	if c.Runnable() {
		sb.WriteString("\n  " + c.UseLine())
	}
	if c.hasSubCommands() {
		sb.WriteString("\n  " + c.CommandPath() + " [command]")
	}
	if c.Example != "" {
		sb.WriteString("\n\nExamples:\n" + c.Example)
	}
	if c.hasSubCommands() {
		sb.WriteString("\n\nAvailable Commands:")
		for _, sub := range c.children {
			if sub.Hidden {
				continue
			}
			sb.WriteString(fmt.Sprintf("\n  %s %s", rpad(sub.Name(), c.namePadding()), sub.Short))
		}
	}
	local := c.localFlags()
	if len(local.flags) > 0 {
		sb.WriteString("\n\nFlags:\n" + strings.TrimRight(local.FlagUsages(), " \t\n"))
	}
	inh := c.inheritedFlags()
	if len(inh.flags) > 0 {
		sb.WriteString("\n\nGlobal Flags:\n" + strings.TrimRight(inh.FlagUsages(), " \t\n"))
	}
	if c.hasSubCommands() {
		sb.WriteString(fmt.Sprintf("\n\nUse \"%s [command] --help\" for more information about a command.", c.CommandPath()))
	}
	sb.WriteString("\n")
	return sb.String()
}

func rpad(s string, padding int) string {
	if len(s) >= padding {
		return s
	}
	return s + strings.Repeat(" ", padding-len(s))
}

func (c *Command) HelpString() string {
	var sb strings.Builder
	desc := c.Long
	if desc == "" {
		desc = c.Short
	}
	if desc != "" {
		sb.WriteString(strings.TrimRight(desc, " \t\n") + "\n\n")
	}
	if c.Runnable() || c.hasSubCommands() {
		sb.WriteString(c.UsageString())
	}
	return sb.String()
}

func (c *Command) PrintHelp() { fmt.Fprint(stdout, c.HelpString()) }

func (c *Command) findSub(name string) *Command {
	for _, sub := range c.children {
		if sub.Name() == name {
			return sub
		}
	}
	return nil
}

var stdout = os.Stdout
var stderr = os.Stderr

// suggestionsFor mirrors cobra's suggestion mechanism.
func (c *Command) suggestionsFor(arg string) []string {
	var out []string
	for _, sub := range c.children {
		if sub.Hidden {
			continue
		}
		ld := levenshtein(arg, sub.Name(), true)
		if ld <= 2 || strings.HasPrefix(strings.ToLower(sub.Name()), strings.ToLower(arg)) {
			out = append(out, sub.Name())
		}
	}
	return out
}

func levenshtein(a, b string, ignoreCase bool) int {
	if ignoreCase {
		a = strings.ToLower(a)
		b = strings.ToLower(b)
	}
	la, lb := len(a), len(b)
	if la == 0 {
		return lb
	}
	if lb == 0 {
		return la
	}
	prev := make([]int, lb+1)
	cur := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		cur[0] = i
		for j := 1; j <= lb; j++ {
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			m := prev[j] + 1
			if cur[j-1]+1 < m {
				m = cur[j-1] + 1
			}
			if prev[j-1]+cost < m {
				m = prev[j-1] + cost
			}
			cur[j] = m
		}
		prev, cur = cur, prev
	}
	return prev[lb]
}

// find locates the deepest command matching args, returning the remaining args.
func (c *Command) find(args []string) (*Command, []string, error) {
	cmd := c
	rest := args
	for {
		// find the first non-flag argument
		next, idx := firstNonFlag(cmd, rest)
		if idx < 0 {
			return cmd, rest, nil
		}
		sub := cmd.findSub(next)
		if sub == nil {
			break
		}
		rest = append(append([]string{}, rest[:idx]...), rest[idx+1:]...)
		cmd = sub
	}
	if !cmd.hasSubCommands() {
		return cmd, rest, nil
	}
	if cmd.Parent == nil && len(rest) > 0 {
		// root command with subcommands: unknown command error
		msg := fmt.Sprintf("unknown command %q for %q", rest[0], cmd.CommandPath())
		if s := cmd.suggestionsFor(rest[0]); len(s) > 0 {
			msg += "\n\nDid you mean this?\n"
			for _, x := range s {
				msg += "\t" + x + "\n"
			}
		}
		return cmd, rest, fmt.Errorf("%s", msg)
	}
	return cmd, rest, nil
}

// firstNonFlag returns the first positional argument and its index.
func firstNonFlag(cmd *Command, args []string) (string, int) {
	fs := cmd.allFlags()
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			return "", -1
		}
		if strings.HasPrefix(a, "--") {
			body := a[2:]
			name := body
			if j := strings.Index(body, "="); j >= 0 {
				name = body[:j]
			}
			f := fs.byName[name]
			if f == nil {
				// unknown flag; cobra keeps scanning
				continue
			}
			if f.NoOptDefVal == "" {
				if !strings.Contains(body, "=") {
					i++ // skip the value
				}
			}
			continue
		}
		if len(a) > 1 && a[0] == '-' {
			// shorthand; conservatively skip one value unless it is boolean
			continue
		}
		return a, i
	}
	return "", -1
}

// execute runs the command tree with the given arguments.
func (c *Command) execute(args []string) int {
	cmd, rest, err := c.find(args)
	if err != nil {
		fmt.Fprintln(stderr, "Error:", err.Error())
		fmt.Fprintf(stderr, "Run '%v --help' for usage.\n", cmd.CommandPath())
		return 1
	}
	cmd.initHelpFlag()
	fs := cmd.allFlags()
	if err := fs.parse(rest); err != nil {
		fmt.Fprintln(stderr, "Error:", err.Error())
		return 1
	}
	if hf := fs.byName["help"]; hf != nil && hf.Value.String() == "true" {
		cmd.PrintHelp()
		return 0
	}
	positional := fs.args
	if cmd.Args != nil {
		if err := cmd.Args(cmd, positional); err != nil {
			fmt.Fprintln(stderr, "Error:", err.Error())
			return 1
		}
	}
	if err := cmd.validateRequiredFlags(fs); err != nil {
		fmt.Fprintln(stderr, "Error:", err.Error())
		return 1
	}
	if err := cmd.validateOneRequired(fs); err != nil {
		fmt.Fprintln(stderr, "Error:", err.Error())
		return 1
	}
	if cmd.RunE == nil {
		cmd.PrintHelp()
		return 0
	}
	if err := cmd.RunE(cmd, positional); err != nil {
		fmt.Fprintln(stderr, "Error:", err.Error())
		return 1
	}
	return 0
}

func (c *Command) validateRequiredFlags(fs *FlagSet) error {
	var missing []string
	sets := []*FlagSet{c.Flags, c.Persistent}
	for _, s := range sets {
		if s == nil {
			continue
		}
		for _, f := range s.flags {
			if f.Required && !f.Changed {
				missing = append(missing, f.Name)
			}
		}
	}
	sort.Strings(missing)
	if len(missing) > 0 {
		return fmt.Errorf(`required flag(s) "%s" not set`, strings.Join(missing, `", "`))
	}
	return nil
}

func (c *Command) validateOneRequired(fs *FlagSet) error {
	if c.oneRequired == nil {
		return nil
	}
	for _, group := range c.oneRequired {
		var missing []string
		found := false
		for _, name := range group {
			if f := fs.byName[name]; f != nil {
				if f.Changed {
					found = true
				}
				if !f.Hidden {
					missing = append(missing, name)
				}
			}
		}
		if !found && len(missing) > 0 {
			sort.Strings(missing)
			quoted := make([]string, len(missing))
			for i, m := range missing {
				quoted[i] = `"` + m + `"`
			}
			return fmt.Errorf("one of flag(s) %s is required", strings.Join(quoted, " or "))
		}
	}
	return nil
}
