	return nil
}
func (s stringArrayValue) Type() string { return s.typeStr }

// varValue is the value type used for --var, whose type name shows up in the
// help output.
type varValue struct{ p *[]string }

func (v varValue) String() string { return "[" + strings.Join(*v.p, ",") + "]" }
func (v varValue) Set(s string) error {
	kv := strings.SplitN(s, "=", 2)
	if len(kv) != 2 {
		return fmt.Errorf("variables must be format as key=value, got: %q", s)
	}
