package main

import (
	"fmt"
	"net"
	"net/url"
	"strings"
)

// DBURL is a parsed atlas database URL.
type DBURL struct {
	Scheme string
	Host   string
	User   string
	Pass   string
	Path   string
	Query  url.Values
	Raw    string
}

// ParseDBURL parses an atlas resource URL. It mirrors the behaviour of
// atlas's URL parsing, including the error messages produced by net/url.
func ParseDBURL(raw string) (*DBURL, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return nil, err
	}
	out := &DBURL{Scheme: u.Scheme, Raw: raw, Path: u.Path, Query: u.Query()}
	if u.User != nil {
		out.User = u.User.Username()
		out.Pass, _ = u.User.Password()
	}
	out.Host = u.Host
	return out, nil
}

// Driver returns the driver part of the URL scheme (stripping the optional
// "+driver" suffix).
func (u *DBURL) Driver() string {
	s := u.Scheme
	if i := strings.Index(s, "+"); i >= 0 {
		s = s[:i]
	}
	return s
}

func (u *DBURL) Param(key string) string { return u.Query.Get(key) }

func (u *DBURL) Has(key string) bool { _, ok := u.Query[key]; return ok }

// port returns the port for the driver, defaulting per atlas conventions.
func (u *DBURL) port(def string) string {
	if i := strings.LastIndex(u.Host, ":"); i >= 0 && !strings.Contains(u.Host, "]") {
		if p := u.Host[i+1:]; p != "" {
			return p
		}
	}
	if p := u.Param("port"); p != "" {
		return p
	}
	return def
}

func (u *DBURL) addr(def string) string {
	host := u.Host
	if i := strings.LastIndex(host, ":"); i >= 0 && !strings.Contains(host, "]") {
		host = host[:i]
	}
	if host == "" {
		host = "127.0.0.1"
	}
	return net.JoinHostPort(host, u.port(def))
}

// Connect attempts to connect to the database, returning an error that matches
// the message atlas produces when the database is unreachable.
func (u *DBURL) Connect() error {
	switch u.Driver() {
	case "mysql", "mariadb":
		_, err := net.Dial("tcp", u.addr("3306"))
		if err != nil {
			return fmt.Errorf("mysql: query system variables: %s", err)
		}
		return fmt.Errorf("mysql: query system variables: unsupported community edition driver")
	case "postgres", "postgresql":
		_, err := net.Dial("tcp", u.addr("5432"))
		if err != nil {
			return fmt.Errorf("postgres: scanning system variables: %s", err)
		}
		return fmt.Errorf("postgres: scanning system variables: unsupported community edition driver")
	case "docker":
		return fmt.Errorf("exec: \"docker\": executable file not found in $PATH")
	}
	return nil
}
