package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// sqliteDSN computes the on-disk path used by the sqlite driver for the given
// URL.
func sqliteDSN(u *DBURL) string {
	dsn := u.Host + u.Path
	if dsn == "" {
		return "sqlite:"
	}
	return dsn
}

// sqliteOpen opens (creating if needed) the database file for the given URL.
func sqliteOpen(u *DBURL) (string, error) {
	dsn := sqliteDSN(u)
	if dsn == "" || dsn == "sqlite:" {
		return "", nil
	}
	if strings.HasPrefix(dsn, "file:") {
		dsn = strings.TrimPrefix(dsn, "file:")
	}
	if i := strings.IndexAny(dsn, "?"); i >= 0 {
		dsn = dsn[:i]
	}
	f, err := os.OpenFile(dsn, os.O_RDWR|os.O_CREATE, 0644)
	if err != nil {
		if os.IsNotExist(err) {
			return "", fmt.Errorf("sqlite: querying schemas: unable to open database file: no such file or directory")
		}
		return "", fmt.Errorf("sqlite: querying schemas: unable to open database file: %s", unwrapSyscall(err))
	}
	f.Close()
	return dsn, nil
}

// unwrapSyscall converts os errors into the plain sqlite error strings.
func unwrapSyscall(err error) string {
	var pe *os.PathError
	if errors.As(err, &pe) {
		return pe.Err.Error()
	}
	return err.Error()
}

// sqliteSchema returns the HCL representation of the inspected schema.
func sqliteSchema(u *DBURL, schemaNames []string, exclude []string) (string, error) {
	dsn, err := sqliteOpen(u)
	if err != nil {
		return "", err
	}
	names := schemaNames
	if len(names) == 0 {
		names = []string{"main"}
	}
	var sb strings.Builder
	for _, n := range names {
		if len(names) > 1 {
			sb.WriteString("\n")
		}
		sb.WriteString("schema \"" + n + "\" {\n}\n")
	}
	_ = dsn
	_ = exclude
	_ = filepath.Base
	return sb.String(), nil
}
