{"command": "cat > /workspace/hclparse.go <<'GOEOF'
package main

import (
	"fmt"
	"strings"
)

// Pos is a 1-based source position.
type Pos struct {
	Line, Col, EndCol int
}

func (p Pos) String() string { return fmt.Sprintf("%d,%d-%d", p.Line, p.Col, p.EndCol) }

// Diag is a parse diagnostic.
type Diag struct {
	Pos     Pos
	File    string
	Summary string
	Detail  string
}

func (d Diag) Error() string {
	return fmt.Sprintf("%s:%s: %s; %s", d.File, d.Pos, d.Summary, d.Detail)
}

type diags []Diag

func (ds diags) Error() string {
	s := ""
	for i, d := range ds {
		if i > 0 {
			s += "\n"
		}
		s += d.Error()
	}
	if len(ds) > 1 {
		s += fmt.Sprintf(", and %d other diagnostic(s)", len(ds)-1)
	}
	return s
}

// Expr nodes ---------------------------------------------------------------

type Expr interface{ pos() Pos }

type LitExpr struct {
	Parts []ExprPart
	P     Pos
}

func (e *LitExpr) pos() Pos { return e.P }

type ExprPart struct {
	Raw    string // literal text
	IsExpr bool
	Expr   Expr
}

type NumExpr struct {
	Text string
	P    Pos
}

func (e *NumExpr) pos() Pos { return e.P }

type BoolExpr struct {
	Val bool
	P   Pos
}

func (e *BoolExpr) pos() Pos { return e.P }

type NullExpr struct{ P Pos }

func (e *NullExpr) pos() Pos { return e.P }

type RefExpr struct {
	Name string // full dotted path, e.g. "var.db_name"
	P    Pos
}

func (e *RefExpr) pos() Pos { return e.P }

type CallExpr struct {
	Name string
	Args []Expr
	P    Pos
}

func (e *CallExpr) pos() Pos { return e.P }

type ListExpr struct {
	Items []Expr
	P     Pos
}

func (e *ListExpr) pos() Pos { return e.P }

type ObjectExpr struct {
	Keys  []string
	Exprs []Expr
	P     Pos
}

func (e *ObjectExpr) pos() Pos { return e.P }

// Body / Attr / Block ------------------------------------------------------

type Attr struct {
	Name   string
	NameP  Pos
	Expr   Expr
	P      Pos
}

type Block struct {
	Name   string
	NameP  Pos
	Labels []string
	Body   *Body
	P      Pos
}

type Body struct {
	Attrs   map[string]*Attr
	Blocks  []*Block
	Order   []string // "attr:NAME" or "block:NAME"
	SrcP    Pos
	EndP    Pos
}

func newBody() *Body { return &Body{Attrs: map[string]*Attr{}} }

// parser ------------------------------------------------------------------

type parser struct {
	toks []Tok
	i    int
	file string
	ds   diags
}

func (p *parser) peek() Tok {
	if p.i < len(p.toks) {
		return p.toks[p.i]
	}
	return Tok{Kind: KIdent, Text: ""}
}
func (p *parser) next() Tok {
	t := p.toks[p.i]
	p.i++
	return t
}
func (p *parser) tokPos(t Tok) Pos { return Pos{Line: t.Line, Col: t.Col, EndCol: t.End} }
func (p *parser) errf(pos Pos, summary, detail string) {
	p.ds = append(p.ds, Diag{Pos: pos, File: p.file, Summary: summary, Detail: detail})
}

// parseBody parses a sequence of attributes and blocks until EOF or '}'.
func (p *parser) parseBody(closer byte) *Body {
	b := newBody()
	for {
		t := p.peek()
		if t.Kind == KNewline {
			p.next()
			continue
		}
		if p.i >= len(p.toks) {
			if closer != 0 {
				// unclosed block: report at the opening brace
				return b
			}
			return b
		}
		if t.Kind == KCHBrace {
			if closer == 0 {
				p.errf(p.tokPos(t), "Argument or block definition required", "An argument or block definition is required here.")
			}
			p.next()
			return b
		}
		if t.Kind == KComment {
			p.next()
			continue
		}
		if t.Kind != KIdent {
			p.errf(p.tokPos(t), "Argument or block definition required", "An argument or block definition is required here.")
			// skip to the end of the line
			for p.i < len(p.toks) && p.toks[p.i].Kind != KNewline {
				p.next()
			}
			continue
		}
		ident := p.next()
		start := p.tokPos(ident)
		// labels
		var labels []string
		for {
			n := p.peek()
			if n.Kind == KString || n.Kind == KIdent {
				labels = append(labels, strings.Trim(n.Text, "\""))
				p.next()
				continue
			}
			break
		}
		n := p.peek()
		switch n.Kind {
		case KEqual:
			p.next()
			expr, ok := p.parseExpr()
			if !ok {
				// skip to newline
				for p.i < len(p.toks) && p.toks[p.i].Kind != KNewline {
					p.next()
				}
				continue
			}
			// after the value, a newline or comment is required
			nx := p.peek()
			if nx.Kind != KNewline && nx.Kind != KComment && p.i < len(p.toks) {
				p.errf(p.tokPos(nx), "Missing newline after argument", "An argument definition must end with a newline.")
				for p.i < len(p.toks) && p.toks[p.i].Kind != KNewline {
					p.next()
				}
			}
			if _, exists := b.Attrs[ident.Text]; exists {
				prev := b.Attrs[ident.Text]
				p.errf(p.tokPos(ident), "Attribute redefined",
					fmt.Sprintf("The argument %q was already set at %s:%s. Each argument may be set only once.", ident.Text, p.file, prev.NameP))
			} else {
				b.Attrs[ident.Text] = &Attr{Name: ident.Text, NameP: p.tokPos(ident), Expr: expr, P: start}
			}
			b.Order = append(b.Order, "attr:"+ident.Text)
		case KOHBrace:
			// block
			bp := p.tokPos(n)
			p.next()
			body := p.parseBody('}')
			if len(labels) == 0 {
				labels = nil
			}
			b.Blocks = append(b.Blocks, &Block{Name: ident.Text, NameP: start, Labels: labels, Body: body, P: start})
			b.Order = append(b.Order, "block:"+ident.Text)
		case KNewline, KComment:
			// attribute or block without a value
			if closer == 0 {
				p.errf(start, "Argument or block definition required",
					"An argument or block definition is required here. To set an argument, use the equals sign \"=\" to introduce the argument value.")
			} else {
				// inside a block: single-line block definition
				p.errf(start, "Invalid block definition",
					"A block definition must have block content delimited by \"{\" and \"}\", starting on the same line as the block header.")
			}
			if n.Kind == KComment {
				p.next()
			}
			if n.Kind == KNewline {
				p.next()
			}
		default:
			// something else: invalid block definition
			p.errf(start, "Invalid block definition",
				"A block definition must have block content delimited by \"{\" and \"}\", starting on the same line as the block header.")
			for p.i < len(p.toks) && p.toks[p.i].Kind != KNewline {
				p.next()
			}
		}
	}
}

// parseExpr parses an expression on a single line.
func (p *parser) parseExpr() (Expr, bool) {
	t := p.peek()
	switch t.Kind {
	case KString:
		p.next()
		return parseTemplateExpr(t.Text, p.tokPos(t)), true
	case KNumber:
		p.next()
		return &NumExpr{Text: t.Text, P: p.tokPos(t)}, true
	case KIdent:
		p.next()
		switch t.Text {
		case "true":
			return &BoolExpr{Val: true, P: p.tokPos(t)}, true
		case "false":
			return &BoolExpr{Val: false, P: p.tokPos(t)}, true
		case "null":
			return &NullExpr{P: p.tokPos(t)}, true
		}
		// function call?
		if p.peek().Kind == KOParen {
			p.next()
			call := &CallExpr{Name: t.Text, P: p.tokPos(t)}
			for {
				n := p.peek()
				if n.Kind == KCParen {
					p.next()
					break
				}
				if n.Kind == KComma {
					p.next()
					continue
				}
				if n.Kind == KNewline || p.i >= len(p.toks) {
					break
				}
				arg, ok := p.parseExpr()
				if !ok {
					break
				}
				call.Args = append(call.Args, arg)
			}
			return call, true
		}
		// dotted reference
		name := t.Text
		for p.peek().Kind == KDot {
			p.next()
			nx := p.peek()
			if nx.Kind != KIdent && nx.Kind != KNumber {
				break
			}
			p.next()
			name += "." + nx.Text
		}
		return &RefExpr{Name: name, P: p.tokPos(t)}, true
	case KOBrack:
		p.next()
		list := &ListExpr{P: p.tokPos(t)}
		for {
			n := p.peek()
			if n.Kind == KCBrack {
				p.next()
				break
			}
			if n.Kind == KComma {
				p.next()
				continue
			}
			if n.Kind == KNewline || p.i >= len(p.toks) {
				p.next()
				break
			}
			it, ok := p.parseExpr()
			if !ok {
				break
			}
			list.Items = append(list.Items, it)
		}
		return list, true
	case KOHBrace:
		p.next()
		obj := &ObjectExpr{P: p.tokPos(t)}
		for {
			n := p.peek()
			if n.Kind == KCHBrace {
				p.next()
				break
			}
			if n.Kind == KComma || n.Kind == KNewline {
				p.next()
				continue
			}
			if n.Kind != KIdent && n.Kind != KString {
				break
			}
			key := strings.Trim(n.Text, "\"")
			p.next()
			if p.peek().Kind != KEqual {
				break
			}
			p.next()
