				continue
			}
			if n.Kind == KNewline || p.i >= len(p.toks) {
				p.next()
				break
			}
			it, ok := p.parseExpr()
			if !ok {
				break
			}
			list.Items = append(list.Items, it)
		}
		return list, true
	case KOHBrace:
		p.next()
		obj := &ObjectExpr{P: p.tokPos(t)}
		for {
			n := p.peek()
			if n.Kind == KCHBrace {
				p.next()
				break
			}
			if n.Kind == KComma || n.Kind == KNewline {
				p.next()
				continue
			}
			if n.Kind != KIdent && n.Kind != KString {
				break
			}
			key := strings.Trim(n.Text, "\"")
			p.next()
			if p.peek().Kind != KEqual {
				break
			}
			p.next()
			v, ok := p.parseExpr()
			if !ok {
				break
			}
			obj.Keys = append(obj.Keys, key)
			obj.Exprs = append(obj.Exprs, v)
		}
		return obj, true
	case KNegate, KMinus:
		p.next()
		inner, ok := p.parseExpr()
		if !ok {
			return nil, false
		}
		return inner, true
	case KComment:
		p.next()
		return p.parseExpr()
	}
	return nil, false
