					break
				}
				arg, ok := p.parseExpr()
				if !ok {
					break
				}
				call.Args = append(call.Args, arg)
			}
			return call, true
		}
		// dotted reference
		name := t.Text
		for p.peek().Kind == KDot {
			p.next()
			nx := p.peek()
			if nx.Kind != KIdent && nx.Kind != KNumber {
				break
			}
			p.next()
			name += "." + nx.Text
		}
		return &RefExpr{Name: name, P: p.tokPos(t)}, true
	case KOBrack:
		p.next()
		list := &ListExpr{P: p.tokPos(t)}
		for {
			n := p.peek()
			if n.Kind == KCBrack {
				p.next()
				break
			}
			if n.Kind == KComma {
				p.next()
				continue
			}
			if n.Kind == KNewline || p.i >= len(p.toks) {
				p.next()
				break
			}
			it, ok := p.parseExpr()
			if !ok {
				break
			}
			list.Items = append(list.Items, it)
		}
		return list, true
	case KOHBrace:
		p.next()
		obj := &ObjectExpr{P: p.tokPos(t)}
		for {
			n := p.peek()
			if n.Kind == KCHBrace {
				p.next()
				break
			}
			if n.Kind == KComma || n.Kind == KNewline {
				p.next()
				continue
			}
			if n.Kind != KIdent && n.Kind != KString {
				break
			}
			key := strings.Trim(n.Text, "\"")
			p.next()
			if p.peek().Kind != KEqual {
				break
			}
			p.next()
			v, ok := p.parseExpr()
			if !ok {
				break
			}
			obj.Keys = append(obj.Keys, key)
			obj.Exprs = append(obj.Exprs, v)
		}
		return obj, true
	case KNegate, KMinus:
		p.next()
		inner, ok := p.parseExpr()
		if !ok {
			return nil, false
		}
		return inner, true
	case KComment:
		p.next()
		return p.parseExpr()
	}
	return nil, false
}

// parseTemplateExpr converts a string literal into a LitExpr, splitting the
// interpolation parts.
func parseTemplateExpr(text string, p Pos) Expr {
	e := &LitExpr{P: p}
	i := 0
	// strip the surrounding quotes
	if strings.HasPrefix(text, "\"") {
		text = text[1:]
		if strings.HasSuffix(text, "\"") {
			text = text[:len(text)-1]
		}
	}
	for i < len(text) {
		if text[i] == '\\' && i+1 < len(text) {
			raw := text[i : i+2]
			switch raw[1] {
			case 'n':
				e.Parts = append(e.Parts, ExprPart{Raw: "\n"})
			case 't':
				e.Parts = append(e.Parts, ExprPart{Raw: "\t"})
			case 'r':
				e.Parts = append(e.Parts, ExprPart{Raw: "\r"})
			default:
				e.Parts = append(e.Parts, ExprPart{Raw: string(raw[1])})
			}
			i += 2
			continue
		}
		if (text[i] == '$' || text[i] == '%') && i+1 < len(text) && text[i+1] == '{' {
			depth := 1
			j := i + 2
			for j < len(text) && depth > 0 {
				switch text[j] {
				case '{':
					depth++
				case '}':
					depth--
				case '"':
					j = scanStringAt(text, j)
					continue
				}
				j++
			}
			inner := text[i+2 : j]
			sub := tokenize(inner)
			pp := &parser{toks: sub, file: ""}
			ex, _ := pp.parseExpr()
			e.Parts = append(e.Parts, ExprPart{IsExpr: true, Expr: ex})
			i = j + 1
			continue
		}
		e.Parts = append(e.Parts, ExprPart{Raw: string(text[i])})
		i++
	}
	return e
}
