func runHelp(c *Command, args []string) error {
	root := c
	for root.Parent != nil {
		root = root.Parent
	}
	if len(args) == 0 {
		root.PrintHelp()
		return nil
	}
	target, rest, err := root.find(args)
	if err != nil || len(rest) > 0 || (target == root && len(args) > 0) {
		fmt.Fprintf(stdout, "Unknown help topic %s\n", goQuoteSlice(args))
		// cobra prints the root usage without the implicit help flag
		root.helpFlag = nil
		fmt.Fprint(stdout, root.UsageString())
		return nil
	}
	target.initHelpFlag()
	target.PrintHelp()
	return nil
