func stateDir() string {
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".atlas")
}

func readState(name string) map[string]string {
	m := map[string]string{}
	b, err := os.ReadFile(filepath.Join(stateDir(), name))
	if err != nil {
		return m
	}
	for _, kv := range strings.Split(strings.Trim(strings.TrimSpace(string(b)), "{}"), ",") {
		parts := strings.SplitN(kv, ":", 2)
		if len(parts) != 2 {
			continue
		}
		m[strings.Trim(parts[0], `"`)] = strings.Trim(parts[1], `"`)
	}
	return m
}

func writeState(name string, m map[string]string) {
	dir := stateDir()
	if dir == "" {
		return
	}
	_ = os.MkdirAll(dir, 0755)
	var keys []string
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, fmt.Sprintf("%q:%q", k, m[k]))
	}
	_ = os.WriteFile(filepath.Join(dir, name), []byte("{"+strings.Join(parts, ",")+"}"), 0644)
}

// notifyCommunity prints the community notice once per user.
func notifyCommunity() {
	m := readState("local-community.json")
	if _, ok := m["v1.us"]; ok {
		return
	}
	fmt.Fprint(stderr, communityNotice)
	m["v1.us"] = time.Now().UTC().Format(time.RFC3339Nano)
	writeState("local-community.json", m)
}

// communityHint prints the community hint after an error, at most once per day.
func communityHint() {
	m := readState("community_error.json")
	if t, ok := m["last_suggested"]; ok {
		if tt, err := time.Parse(time.RFC3339Nano, t); err == nil {
			if time.Since(tt) < 24*time.Hour {
				return
			}
		} else if t != "" {
			return
		}
	}
	fmt.Fprint(stderr, communityError)
	m["last_suggested"] = time.Now().UTC().Format(time.RFC3339Nano)
	writeState("community_error.json", m)
}

// ---------------------------------------------------------------------------
// URLs and states
// ---------------------------------------------------------------------------

var errMissingDriver = fmt.Errorf("sql/sqlclient: missing driver. See: https://atlasgo.io/url")

// openState validates and "opens" the given resource URL.
func openState(raw string) (*DBURL, error) {
	u, err := ParseDBURL(raw)
	if err != nil {
		return nil, unwrapURLError(err)
	}
	switch strings.ToLower(u.Scheme) {
	case "":
		return nil, errMissingDriver
	case "atlas":
		return nil, errors.New("atlas remote state is not supported by the community version of Atlas.\n\n" +
			"Install the non-community version instead:\n\n\tcurl -sSf https://atlasgo.sh | sh\n\n" +
			"For more installtion options, see: https://atlasgo.io/docs#installation")
	case "mysql", "mariadb", "postgres", "postgresql":
		if err := u.Connect(); err != nil {
			return nil, err
		}
	case "docker":
		return nil, fmt.Errorf("exec: \"docker\": executable file not found in $PATH")
	case "file":
		p := u.Host + u.Path
		if p == "" {
			p = ""
		}
		if _, err := os.Stat(p); err != nil {
			return nil, fmt.Errorf("stat %s: no such file or directory", p)
		}
	case "sqlite":
		// handled by the caller
	default:
		return nil, fmt.Errorf("sql/sqlclient: unknown driver %q. See: https://atlasgo.io/url", u.Scheme)
	}
	return u, nil
}

func unwrapURLError(err error) error {
	var ue *urlError
	if errors.As(err, &ue) {
		return errors.New(ue.err)
	}
	return err
}

type urlError struct{ err string }

func (e *urlError) Error() string { return e.err }

func isURLParseError(err error) bool {
	return err.Error() != "" && strings.Contains(err.Error(), "after host")
}

