	"strings"
)

// ---------------------------------------------------------------------------
// migration directories
// ---------------------------------------------------------------------------

func dirFSPath(raw string) (string, error) {
	if raw == "" {
		return "", errMissingDriver
	}
	u, err := ParseDBURL(raw)
	if err != nil {
		return "", unwrapURLError(err)
	}
