			"For more installtion options, see: https://atlasgo.io/docs#installation")
	case "":
		return "", errMissingDriver
	default:
		return "", fmt.Errorf("sql/migrate: unsupported dir url %q", raw)
	}
}

func listMigrationFiles(dir string) ([]string, error) {
	st, err := os.Stat(dir)
	if err != nil {
		return nil, fmt.Errorf("sql/migrate: stat %s: no such file or directory", dir)
	}
	if !st.IsDir() {
		return nil, fmt.Errorf("sql/migrate: stat %s: not a directory", dir)
	}
	ents, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var files []string
	for _, e := range ents {
		if strings.HasSuffix(e.Name(), ".sql") {
			files = append(files, e.Name())
		}
	}
	sort.Strings(files)
	for _, f := range files {
		info, err := os.Stat(filepath.Join(dir, f))
		if err == nil && info.IsDir() {
			return nil, fmt.Errorf("sql/migrate: read file %q: read %s/%s: is a directory", f, dir, f)
		}
	}
	return files, nil
}

// hashFiles computes the per-file (cumulative) hashes and the directory hash.
func hashFiles(dir string, files []string) (string, map[string]string) {
	h := sha256.New()
	per := make(map[string]string, len(files))
	for _, f := range files {
		h.Write([]byte(f))
		content, err := os.ReadFile(filepath.Join(dir, f))
		if err != nil {
			content = []byte{}
		}
		h.Write(content)
		per[f] = "h1:" + base64.StdEncoding.EncodeToString(h.Sum(nil))
	}
	dh := sha256.New()
	for _, f := range files {
		dh.Write([]byte(f))
		dh.Write([]byte(per[f]))
	}
	return "h1:" + base64.StdEncoding.EncodeToString(dh.Sum(nil)), per
}

func readSumFile(dir string) (string, []string, map[string]string, bool) {
	b, err := os.ReadFile(filepath.Join(dir, "atlas.sum"))
	if err != nil {
		return "", nil, nil, false
	}
	lines := strings.Split(strings.TrimRight(string(b), "\n"), "\n")
	if len(lines) == 0 {
		return "", nil, nil, false
	}
	var order []string
	m := map[string]string{}
	for _, l := range lines[1:] {
		if strings.TrimSpace(l) == "" {
			continue
		}
		parts := strings.SplitN(l, " ", 2)
		if len(parts) != 2 {
			continue
		}
		name := parts[0]
		h := strings.TrimPrefix(parts[1], "h1:")
		order = append(order, name)
		m[name] = h
	}
	return strings.TrimPrefix(lines[0], "h1:"), order, m, true
}

func writeSumFile(dir, dirHash string, files []string, per map[string]string) error {
	var sb strings.Builder
	sb.WriteString(dirHash + "\n")
	for _, f := range files {
		sb.WriteString(fmt.Sprintf("%s %s\n", f, per[f]))
	}
	return os.WriteFile(filepath.Join(dir, "atlas.sum"), []byte(sb.String()), 0644)
}

// validateDir validates the checksum file and returns the error describing the
// first mismatch, or nil.
func validateDir(dir string) error {
	files, err := listMigrationFiles(dir)
	if err != nil {
		return err
	}
	dirHash, order, sums, ok := readSumFile(dir)
	if !ok {
		fmt.Fprintln(stderr, "You have a checksum error in your migration directory.")
		fmt.Fprintln(stderr, "Please check your migration files and run 'atlas migrate hash' to re-hash the contents")
		fmt.Fprintln(stderr)
		return errors.New("checksum file not found")
	}
	sumFiles := []string{}
	for _, f := range order {
		sumFiles = append(sumFiles, f)
	}
	// compute the expected hashes
	_, per := hashFiles(dir, files)
	// determine the first difference, mirroring atlas's reported line numbers
	lineNo := 1
	found := ""
	for _, f := range order {
		lineNo++
		p := filepath.Join(dir, f)
		if _, err := os.Stat(p); err != nil {
			found = fmt.Sprintf("L%d: %s was removed", lineNo, f)
			break
		}
		if _, expected := per[f]; !expected {
			continue
		}
		if per[f] != sums[f] {
			found = fmt.Sprintf("L%d: %s was edited", lineNo, f)
			break
		}
	}
	if found == "" {
		for _, f := range files {
			if _, ok := sums[f]; !ok {
				found = fmt.Sprintf("L%d: %s was added", lineNo+1, f)
				break
			}
		}
	}
	if found != "" {
		fmt.Fprintln(stderr, "You have a checksum error in your migration directory.")
		fmt.Fprintln(stderr)
		fmt.Fprintln(stderr, "\t"+found)
		fmt.Fprintln(stderr)
		fmt.Fprintln(stderr, "Please check your migration files and run 'atlas migrate hash' to re-hash the contents")
		fmt.Fprintln(stderr)
		return errors.New("checksum mismatch")
	}
	return nil
}

