	sb.WriteString(dirHash + "\n")
	for _, f := range files {
		sb.WriteString(fmt.Sprintf("%s %s\n", f, per[f]))
	}
	return os.WriteFile(filepath.Join(dir, "atlas.sum"), []byte(sb.String()), 0644)
}

// validateDir validates the checksum file and returns the error describing the
// first mismatch, or nil.
func validateDir(dir string) error {
	files, err := listMigrationFiles(dir)
	if err != nil {
		return err
	}
	dirHash, order, sums, ok := readSumFile(dir)
	if !ok {
		fmt.Fprintln(stderr, "You have a checksum error in your migration directory.")
		fmt.Fprintln(stderr, "Please check your migration files and run 'atlas migrate hash' to re-hash the contents")
		fmt.Fprintln(stderr)
		return errors.New("checksum file not found")
	}
	sumFiles := []string{}
	for _, f := range order {
		sumFiles = append(sumFiles, f)
	}
	// compute the expected hashes
	_, per := hashFiles(dir, files)
	// determine the first difference, mirroring atlas's reported line numbers
	lineNo := 1
	found := ""
	for _, f := range order {
		lineNo++
		p := filepath.Join(dir, f)
		if _, err := os.Stat(p); err != nil {
			found = fmt.Sprintf("L%d: %s was removed", lineNo, f)
			break
		}
		if _, expected := per[f]; !expected {
			continue
		}
		if per[f] != sums[f] {
			found = fmt.Sprintf("L%d: %s was edited", lineNo, f)
			break
		}
	}
	if found == "" {
		for _, f := range files {
			if _, ok := sums[f]; !ok {
				found = fmt.Sprintf("L%d: %s was added", lineNo+1, f)
				break
			}
		}
	}
	if found != "" {
		fmt.Fprintln(stderr, "You have a checksum error in your migration directory.")
		fmt.Fprintln(stderr)
		fmt.Fprintln(stderr, "\t"+found)
		fmt.Fprintln(stderr)
		fmt.Fprintln(stderr, "Please check your migration files and run 'atlas migrate hash' to re-hash the contents")
		fmt.Fprintln(stderr)
		return errors.New("checksum mismatch")
	}
	return nil
}

func runMigrateHash(c *Command, args []string) error {
	if _, err := needConfig(); err != nil {
		return err
	}
	dir, err := dirFSPath(o.dir)
	if err != nil {
		return err
	}
	files, err := listMigrationFiles(dir)
	if err != nil {
		return err
	}
	dirHash, per := hashFiles(dir, files)
	if err := writeSumFile(dir, dirHash, files, per); err != nil {
		return err
	}
	return nil
}

func runMigrateNew(c *Command, args []string) error {
	if _, err := needConfig(); err != nil {
		return err
	}
	dir, err := dirFSPath(o.dir)
	if err != nil {
		return err
	}
	if err := validateDir(dir); err != nil {
		return err
	}
	name := ""
	if len(args) > 0 {
		name = args[0]
	}
	version := time.Now().Format("20060102150405")
	fname := version
	if name != "" {
		fname += "_" + name
	}
	fname += ".sql"
	if _, err := os.Stat(filepath.Join(dir, fname)); err == nil {
		return fmt.Errorf("sql/migrate: file %q already exists", fname)
	}
	if err := os.WriteFile(filepath.Join(dir, fname), []byte{}, 0644); err != nil {
		return err
	}
	files, err := listMigrationFiles(dir)
	if err != nil {
		return err
	}
	dirHash, per := hashFiles(dir, files)
	if err := writeSumFile(dir, dirHash, files, per); err != nil {
		return err
	}
	return nil
}

