	if _, err := needConfig(); err != nil {
		return err
	}
	dir, err := dirFSPath(o.dir)
	if err != nil {
		return err
	}
	if err := validateDir(dir); err != nil {
		return err
	}
	return nil
}

func runMigrateStatus(c *Command, args []string) error {
	if _, err := needConfig(); err != nil {
		return err
	}
	u, err := openState(o.url)
	if err != nil {
		return err
	}
	dir, err := dirFSPath(o.dir)
	if err != nil {
		return err
	}
	files, err := listMigrationFiles(dir)
	if err != nil {
		return err
	}
	_ = u
	if err := validateDir(dir); err != nil {
		return err
	}
	fmt.Fprintln(stdout, "Migration Status: PENDING")
	fmt.Fprintln(stdout, "  -- Current Version: No migration applied yet")
	if len(files) > 0 {
		fmt.Fprintln(stdout, "  -- Next Version:    "+strings.TrimSuffix(files[len(files)-1], ".sql"))
		fmt.Fprintf(stdout, "  -- Executed Files:  0 out of %d\n", len(files))
		fmt.Fprintf(stdout, "  -- Pending Files:   %d\n", len(files))
	} else {
		fmt.Fprintln(stdout, "  -- Next Version:    Unknown (no migrations found)")
		fmt.Fprintln(stdout, "  -- Executed Files:  0 out of 0")
		fmt.Fprintln(stdout, "  -- Pending Files:   0")
	}
	return nil
}

func runMigrateApply(c *Command, args []string) error {
	if _, err := needConfig(); err != nil {
		return err
	}
	if o.url == "" {
		return errors.New(`required flag "url" not set`)
	}
	u, err := openState(o.url)
	if err != nil {
		return err
	}
	dir, err := dirFSPath(o.dir)
	if err != nil {
		return err
	}
	if err := validateDir(dir); err != nil {
		return err
	}
	files, err := listMigrationFiles(dir)
	if err != nil {
		return err
	}
	_ = u
	if len(files) == 0 {
		fmt.Fprintln(stdout, "No migration files to apply")
		return nil
	}
	fmt.Fprintf(stdout, "Migrating to version %s (%d migrations in total):\n", strings.TrimSuffix(files[len(files)-1], ".sql"), len(files))
	for _, f := range files {
		fmt.Fprintf(stdout, "\n  %s\n", f)
	}
	return nil
}

