func runMigrateDiff(c *Command, args []string) error {
	if _, err := needConfig(); err != nil {
		return err
	}
	for _, t := range o.to {
		if _, err := openState(t); err != nil {
			return err
		}
	}
	du, err := openState(o.devURL)
	if err != nil {
		return err
	}
	dir, err := dirFSPath(o.dir)
	if err != nil {
		return err
	}
	if err := validateDir(dir); err != nil {
		return err
	}
	_, _ = du, dir
	return errors.New("sql/migrate: unsupported")
}

