{"command": "rm -rf /workspace/src /workspace/tmpdbg.go; cat > /workspace/main.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

type opts struct {
	config      string
	env         string
	vars        []string
	url         string
	to          []string
	devURL      string
	schemas     []string
	exclude     []string
	include     []string
	format      string
	dir         string
	dirFormat   string
	txMode      string
	lockTimeout time.Duration
	baseline    string
	latest      uint
	gitBase     string
	gitDir      string
	plan        string
	file        string
	edit        bool
	dryRun      bool
	autoApprove bool
	revisions   string
	execOrder   string
	allowDirty  bool
	qualifier   string
	from        string
	froms       []string

	urlSet     bool
	toSet      bool
	devSet     bool
	dirSet     bool
	schemasSet bool
}

var o = &opts{}

func addGlobalFlags(c *Command) {
	c.Persistent = NewFlagSet()
	c.Persistent.StringVarP(&o.config, "config", "c", "file://atlas.hcl", "select config (project) file using URL format")
	c.Persistent.StringVar(&o.env, "env", "", "set which env from the config file to use")
	c.Persistent.VarVar(&o.vars, "var", nil, "input variables")
}

func buildRoot() *Command {
	root := &Command{Use: "atlas", Short: "Manage your database schema as code", Long: long_root, SilenceUsage: true}

	schema := &Command{sortFlags: true, Use: "schema", Short: "Work with atlas schemas.", Long: long_schema}
	addGlobalFlags(schema)
	schema.AddCommand(
		newSchemaApply(), newSchemaClean(), newSchemaDiff(), newSchemaFmt(), newSchemaInspect(),
	)

	migrate := &Command{sortFlags: true, Use: "migrate", Short: "Manage versioned migration files", Long: long_migrate}
	addGlobalFlags(migrate)
	migrate.AddCommand(
		newMigrateApply(), newMigrateDiff(), newMigrateHash(), newMigrateImport(),
		newMigrateLint(), newMigrateNew(), newMigrateSet(), newMigrateStatus(), newMigrateValidate(),
	)

	comp := &Command{sortFlags: true, Use: "completion", Short: "Generate the autocompletion script for the specified shell", Long: long_completion}
	comp.AddCommand(newCompletion("bash"), newCompletion("zsh"), newCompletion("fish"), newCompletion("powershell"))

	help := &Command{sortFlags: false, Use: "help [command]", Short: "Help about any command", Long: long_help, RunE: runHelp}

	version := &Command{sortFlags: false, Use: "version", Short: "Prints this Atlas CLI version information.", Long: long_version,
		RunE: func(c *Command, args []string) error {
			fmt.Fprintln(stdout, "atlas unofficial version - development")
			fmt.Fprintln(stdout, "https://github.com/ariga/atlas/releases/latest")
			fmt.Fprintln(stdout, "To download an official version, visit: https://atlasgo.io/getting-started#installation")
			return nil
		}}
	license := &Command{sortFlags: false, Use: "license", Short: "Display license information", Long: long_license,
		RunE: func(c *Command, args []string) error {
			fmt.Fprintln(stdout, "LICENSE")
			fmt.Fprintln(stdout, "Atlas is licensed under Apache 2.0 as found in https://github.com/ariga/atlas/blob/master/LICENSE.")
			return nil
		}}

	root.AddCommand(comp, help, license, migrate, schema, version)
	return root
}

func runHelp(c *Command, args []string) error {
	root := c
	for root.Parent != nil {
		root = root.Parent
	}
	if len(args) == 0 {
		root.PrintHelp()
		return nil
	}
	target, rest, err := root.find(args)
	if err != nil || len(rest) > 0 || (target == root && len(args) > 0) {
		fmt.Fprintf(stdout, "Unknown help topic %s\n", goQuoteSlice(args))
		root.helpFlag = nil
		fmt.Fprint(stdout, root.UsageString())
		return nil
	}
	target.initHelpFlag()
	target.PrintHelp()
	return nil
}

func goQuoteSlice(args []string) string {
	out := "["
	for i, a := range args {
		if i > 0 {
			out += " "
		}
		out += "`" + a + "`"
	}
	return out + "]"
}

func newCompletion(shell string) *Command {
	c := &Command{sortFlags: true, Use: shell, Short: "Generate the autocompletion script for " + shell,
		Long: completionLong(shell), disableFlagsInUse: shell == "bash",
		RunE: func(c *Command, args []string) error {
			fmt.Fprint(stdout, completionScript(shell))
			return nil
		}}
	var nd bool
	c.Flags = NewFlagSet()
	c.Flags.BoolVar(&nd, "no-descriptions", false, "disable completion descriptions")
	return c
}

func completionLong(shell string) string {
	switch shell {
	case "bash":
		return long_completion_bash
	case "zsh":
		return long_completion_zsh
	case "fish":
		return long_completion_fish
	case "powershell":
		return long_completion_powershell
	}
	return ""
}

func newSchemaFmt() *Command {
	c := &Command{sortFlags: false, Use: "fmt [path ...]", Short: "Formats Atlas HCL files", Long: long_schema_fmt,
		RunE: runSchemaFmt}
	return c
}

func runSchemaFmt(c *Command, args []string) error {
	paths := args
	if len(paths) == 0 {
		paths = []string{"."}
	}
	var files []string
	for _, p := range paths {
		st, err := os.Stat(p)
		if err != nil {
			return fmt.Errorf("stat %s: no such file or directory", p)
		}
		if st.IsDir() {
			ents, err := os.ReadDir(p)
			if err != nil {
				return err
			}
			var names []string
			for _, e := range ents {
				if strings.HasSuffix(e.Name(), ".hcl") {
					names = append(names, e.Name())
				}
			}
			sort.Strings(names)
			for _, n := range names {
				files = append(files, filepath.Join(p, n))
			}
		} else {
			files = append(files, p)
		}
	}
	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			return err
		}
		formatted := formatHCL(string(b))
		if formatted == string(b) {
			continue
		}
		if err := os.WriteFile(f, []byte(formatted), 0644); err != nil {
			return err
		}
		fmt.Fprintln(stdout, displayPath(f))
	}
	return nil
}

func displayPath(p string) string {
	clean := filepath.Clean(p)
	return clean
}

func cobraMaximumNArgs(n int) func(*Command, []string) error {
	return func(c *Command, args []string) error {
		if n >= 0 && len(args) > n {
			return fmt.Errorf("accepts at most %d arg(s), received %d", n, len(args))
		}
		return nil
	}
}

func main() {
	root := buildRoot()
	code := root.execute(os.Args[1:])
	if code != 0 {
		communityHint()
	}
	os.Exit(code)
