	paths := args
	if len(paths) == 0 {
		paths = []string{"."}
	}
	var files []string
	for _, p := range paths {
		st, err := os.Stat(p)
		if err != nil {
			return fmt.Errorf("stat %s: no such file or directory", p)
		}
		if st.IsDir() {
			ents, err := os.ReadDir(p)
			if err != nil {
				return err
			}
			var names []string
			for _, e := range ents {
				if strings.HasSuffix(e.Name(), ".hcl") {
					names = append(names, e.Name())
				}
			}
