			for _, n := range names {
				files = append(files, filepath.Join(p, n))
			}
		} else {
			files = append(files, p)
		}
	}
	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			return err
		}
		formatted := formatHCL(string(b))
		if formatted == string(b) {
			continue
		}
		if err := os.WriteFile(f, []byte(formatted), 0644); err != nil {
			return err
		}
		fmt.Fprintln(stdout, displayPath(f))
	}
	return nil
}

func displayPath(p string) string {
	clean := filepath.Clean(p)
	return clean
}

func cobraMaximumNArgs(n int) func(*Command, []string) error {
	return func(c *Command, args []string) error {
		if n >= 0 && len(args) > n {
			return fmt.Errorf("accepts at most %d arg(s), received %d", n, len(args))
		}
		return nil
	}
}

func main() {
	root := buildRoot()
	code := root.execute(os.Args[1:])
	if code != 0 {
		communityHint()
	}
	os.Exit(code)
}
