{"command": "cat > /workspace/config.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

type Env struct {
	Name      string
	url       string
	dev       string
	dir       string
	schemas   []string
	exclude   []string
	include   []string
	format    string
	txMode    string
	baseline  string
	dirFormat string
	revisions string
	to        []string
	Values    map[string]string
}

type Config struct {
	Path       string
	Envs       map[string]*Env
	EnvList    []string
	Vars       map[string]string
	VarReq     map[string]bool
	Locals     map[string]string
	LocalsExpr map[string]Expr
}

func loadConfig() (*Config, error) {
	raw := o.config
	if raw == "" {
		return nil, nil
	}
	u, err := ParseDBURL(raw)
	if err != nil {
		return nil, unwrapURLError(err)
	}
	if u.Scheme == "" {
		return nil, fmt.Errorf("missing scheme for config file. Did you mean file://%s?", raw)
	}
	if u.Scheme != "file" {
		return nil, fmt.Errorf("unsupported config file scheme %q", u.Scheme)
	}
	path := u.Host + u.Path
	if path == "" {
		path = "atlas.hcl"
	}
	path = filepath.Clean(path)
	for strings.HasPrefix(path, "/") {
		path = strings.TrimPrefix(path, "/")
	}
	if _, err := os.Stat(path); err != nil {
		return nil, fmt.Errorf("config file %q was not found: stat %s: no such file or directory", path, path)
	}
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return parseConfig(string(b), filepath.Base(path), path)
}

func parseConfig(src, display, path string) (*Config, error) {
	toks := tokenize(src)
	p := &parser{toks: toks, file: display}
	body := p.parseBody(0)
	if len(p.ds) > 0 {
		return nil, p.ds
	}
	cfg := &Config{Path: path, Envs: map[string]*Env{}, Vars: map[string]string{}, VarReq: map[string]bool{}, Locals: map[string]string{}, LocalsExpr: map[string]Expr{}}
	for _, blk := range body.Blocks {
		switch blk.Name {
		case "variable":
			if len(blk.Labels) == 0 {
				continue
			}
			name := blk.Labels[0]
			if a, ok := blk.Body.Attrs["default"]; ok {
				v, err := evalExpr(a.Expr, cfg, "")
				if err == nil {
					cfg.Vars[name] = v
				}
			} else {
				cfg.VarReq[name] = true
			}
		case "locals":
			for k, a := range blk.Body.Attrs {
				cfg.LocalsExpr[k] = a.Expr
			}
		}
	}
	for _, blk := range body.Blocks {
		if blk.Name != "env" || len(blk.Labels) == 0 {
			continue
		}
		e := &Env{Name: blk.Labels[0], Values: map[string]string{}}
		for k, a := range blk.Body.Attrs {
			v, err := evalExpr(a.Expr, cfg, e.Name)
			if err != nil {
				return nil, err
			}
			e.Values[k] = v
		}
		e.url = e.Values["url"]
		e.dev = e.Values["dev"]
		e.dir = e.Values["dir"]
		e.format = e.Values["format"]
		e.txMode = e.Values["tx-mode"]
		e.baseline = e.Values["baseline"]
		e.dirFormat = e.Values["dir-format"]
		e.revisions = e.Values["revisions-schema"]
		if ex, ok := blk.Body.Attrs["schemas"]; ok {
			if lst, ok2 := ex.Expr.(*ListExpr); ok2 {
				for _, it := range lst.Items {
					s, _ := evalExpr(it, cfg, e.Name)
					e.schemas = append(e.schemas, s)
				}
			}
		}
		for _, key := range []string{"exclude", "include", "to"} {
			if ex, ok := blk.Body.Attrs[key]; ok {
				if lst, ok2 := ex.Expr.(*ListExpr); ok2 {
					var vals []string
					for _, it := range lst.Items {
						s, _ := evalExpr(it, cfg, e.Name)
						vals = append(vals, s)
					}
					switch key {
					case "exclude":
						e.exclude = vals
					case "include":
						e.include = vals
					case "to":
						e.to = vals
					}
				}
			}
		}
		cfg.Envs[e.Name] = e
		cfg.EnvList = append(cfg.EnvList, e.Name)
	}
	for _, kv := range o.vars {
		parts := strings.SplitN(kv, "=", 2)
		cfg.Vars[parts[0]] = parts[1]
		delete(cfg.VarReq, parts[0])
	}
	return cfg, nil
}

func evalExpr(e Expr, cfg *Config, envName string) (string, error) {
	switch v := e.(type) {
	case *LitExpr:
		var sb strings.Builder
		for _, part := range v.Parts {
			if part.IsExpr {
				s, err := evalExpr(part.Expr, cfg, envName)
				if err != nil {
					return "", err
				}
				sb.WriteString(s)
			} else {
				sb.WriteString(part.Raw)
			}
		}
		return sb.String(), nil
	case *NumExpr:
		return v.Text, nil
	case *BoolExpr:
		return strconv.FormatBool(v.Val), nil
	case *NullExpr:
		return "", nil
	case *RefExpr:
		switch {
		case v.Name == "atlas.env":
			return envName, nil
		case strings.HasPrefix(v.Name, "var."):
			name := strings.TrimPrefix(v.Name, "var.")
			if val, ok := cfg.Vars[name]; ok {
				return val, nil
			}
			return "", fmt.Errorf("undefined variable %q", name)
		case strings.HasPrefix(v.Name, "local."):
			name := strings.TrimPrefix(v.Name, "local.")
			if val, ok := cfg.Locals[name]; ok {
				return val, nil
			}
			if ex, ok := cfg.LocalsExpr[name]; ok {
				s, err := evalExpr(ex, cfg, envName)
				if err != nil {
					return "", err
				}
				cfg.Locals[name] = s
				return s, nil
			}
			return "", fmt.Errorf("undefined local %q", name)
		}
		return "", fmt.Errorf("unknown reference %q", v.Name)
	case *CallExpr:
		switch v.Name {
		case "getenv":
			if len(v.Args) > 0 {
				name, err := evalExpr(v.Args[0], cfg, envName)
				if err != nil {
					return "", err
				}
				return os.Getenv(name), nil
			}
			return "", nil
		}
		return "", fmt.Errorf("unknown function %q", v.Name)
	case *ListExpr:
		var vals []string
		for _, it := range v.Items {
			s, err := evalExpr(it, cfg, envName)
			if err != nil {
				return "", err
			}
			vals = append(vals, s)
		}
		return strings.Join(vals, ","), nil
	}
	return "", fmt.Errorf("unsupported expression")
}

func applyEnv(cfg *Config) error {
	if o.env == "" {
		return nil
	}
	e, ok := cfg.Envs[o.env]
	if !ok {
		return fmt.Errorf("env %q not defined in config file", o.env)
	}
	if !o.urlSet && e.url != "" {
		o.url = e.url
		o.urlSet = true
	}
	if !o.devSet && e.dev != "" {
		o.devURL = e.dev
		o.devSet = true
	}
	if !o.dirSet && e.dir != "" {
		o.dir = e.dir
		o.dirSet = true
	}
	if !o.toSet && len(e.to) > 0 {
		o.to = e.to
		o.toSet = true
	}
	if !o.schemasSet && len(e.schemas) > 0 {
		o.schemas = e.schemas
		o.schemasSet = true
	}
	if len(e.exclude) > 0 && len(o.exclude) == 0 {
		o.exclude = e.exclude
	}
	if len(e.include) > 0 && len(o.include) == 0 {
		o.include = e.include
	}
	if e.format != "" && o.format == "" {
		o.format = e.format
	}
	if e.txMode != "" {
		o.txMode = e.txMode
	}
	if e.baseline != "" && o.baseline == "" {
		o.baseline = e.baseline
	}
	if e.dirFormat != "" && o.dirFormat == "" {
		o.dirFormat = e.dirFormat
	}
	if e.revisions != "" && o.revisions == "" {
		o.revisions = e.revisions
	}
	return nil
}

func needConfig() (*Config, error) {
	if o.config != "" && o.config != "file://atlas.hcl" {
		cfg, err := loadConfig()
		if err != nil {
			return nil, err
		}
		if err := applyEnv(cfg); err != nil {
			return nil, err
		}
		return cfg, nil
	}
	if o.env != "" {
		cfg, err := loadConfig()
		if err != nil {
			return nil, err
		}
		if err := applyEnv(cfg); err != nil {
			return nil, err
		}
		return cfg, nil
	}
	return nil, nil
}
