{"command": "cd /workspace && python3 - <<'PY'
s=open('hclwrite.go').read()
start=s.index('// formatHCL formats the given HCL source the way hclwrite does.')
end=s.index('func nestEndOf(')
new='''// formatHCL formats the given HCL source the way hclwrite does.
func formatHCL(src string) string {
	toks := tokenize(src)

	var lines []*hclLine
	cur := &hclLine{assign: -1, comment: -1}
	for _, t := range toks {
		if t.Kind == KNewline {
			cur.hasNL = true
			lines = append(lines, cur)
			cur = &hclLine{assign: -1, comment: -1}
			continue
		}
		if cur.assign < 0 && t.Kind == KEqual {
			cur.assign = len(cur.toks)
		}
		cur.toks = append(cur.toks, t)
	}
	if len(cur.toks) > 0 {
		lines = append(lines, cur)
	}

	// compute the indentation of each line using a bracket stack
	var stack []bEntry
	unmatched := map[int]int{}
	raw := 0
	for li, l := range lines {
		before := stackDepth(stack, unmatched)
		for i, t := range l.toks {
			if l.assign == i {
				l.nestAssign = raw
			}
			if t.isBracketOpen() {
				stack = append(stack, bEntry{kind: t.Kind, line: li})
				raw++
			} else if t.isBracketClose() {
				raw--
				if len(stack) > 0 {
					popped := stack[len(stack)-1]
					stack = stack[:len(stack)-1]
					for len(stack) > 0 && stack[len(stack)-1].kind == popped.kind &&
						stack[len(stack)-1].line == li {
						stack = stack[:len(stack)-1]
					}
				} else {
					unmatched[li]++
				}
			}
		}
		l.rawEnd = raw
		after := stackDepth(stack, unmatched)
		l.indent = before
		if after < l.indent {
			l.indent = after
		}
		if l.indent < 0 {
			l.indent = 0
		}
	}

	for _, l := range lines {
		if len(l.toks) == 0 {
			continue
		}
		if l.assign >= 0 {
			l.padWidth = 1
			l.leadWidth = renderedWidth(l.toks[:l.assign])
			l.participate = l.nestAssign == l.rawEnd
		}
		if n := len(l.toks); n >= 2 && l.toks[n-1].Kind == KComment &&
			(strings.HasPrefix(l.toks[n-1].Text, "#") || strings.HasPrefix(l.toks[n-1].Text, "//")) {
			l.comment = n - 1
		}
	}

	// alignment runs
	for i := 0; i < len(lines); i++ {
		if !lines[i].participate {
			continue
		}
		target := lines[i].indent*2 + lines[i].leadWidth
		j := i + 1
		for j < len(lines) && lines[j].participate {
			if w := lines[j].indent*2 + lines[j].leadWidth; w > target {
				target = w
			}
			j++
		}
		target++
		for k := i; k < j; k++ {
			lines[k].padWidth = target - (lines[k].indent*2 + lines[k].leadWidth)
			if lines[k].padWidth < 1 {
				lines[k].padWidth = 1
			}
		}
		i = j - 1
	}

	// compute the rendered prefix (everything before a trailing comment)
	for _, l := range lines {
		l.contentW = len(renderPrefix(l))
	}

	// trailing comment alignment
	for i := 0; i < len(lines); i++ {
		if lines[i].comment < 0 {
			continue
		}
		target := lines[i].indent*2 + lines[i].contentW
		j := i + 1
		for j < len(lines) && lines[j].comment >= 0 {
			if w := lines[j].indent*2 + lines[j].contentW; w > target {
				target = w
			}
			j++
		}
		target++
		for k := i; k < j; k++ {
