function.arguments:
{"command": "cd /workspace && python3 - <<'PY'
s=open('config.go').read()
i=s.index('func applyEnv(cfg *Config) error {')
j=s.index('func needConfig(')
new='''func applyEnv(cfg *Config, c *Command) error {
	if o.env == "" {
		return nil
	}
	e, ok := cfg.Envs[o.env]
	if !ok {
		return fmt.Errorf("env %q not defined in config file", o.env)
	}
	fs := c.allFlags()
	apply := func(flagName string, val string) {
		if val == "" {
			return
		}
		f := fs.byName[flagName]
		if f == nil || f.Changed {
			return
		}
		if err := f.Value.Set(val); err != nil {
			return
		}
		f.Changed = true
	}
	apply("url", e.url)
	apply("dev-url", e.dev)
	if len(e.schemas) > 0 {
		if f := fs.byName["schema"]; f != nil && !f.Changed {
			_ = f.Value.Set(strings.Join(e.schemas, ","))
			f.Changed = true
		}
	}
	return nil
}

'''
s=s[:i]+new+s[j:]
s=s.replace('''func needConfig() (*Config, error) {
	if o.config != "" && o.config != "file://atlas.hcl" {
		cfg, err := loadConfig()
		if err != nil {
			return nil, err
		}
		if err := applyEnv(cfg); err != nil {
			return nil, err
		}
		return cfg, nil
	}
	if o.env != "" {
		cfg, err := loadConfig()
		if err != nil {
			return nil, err
		}
		if err := applyEnv(cfg); err != nil {
			return nil, err
		}
		return cfg, nil
	}
	return nil, nil
}''','''func needConfigWith(c *Command) (*Config, error) {
	if o.config == "" || o.config == "file://atlas.hcl" {
		if o.env == "" {
			return nil, nil
		}
	}
	cfg, err := loadConfig()
	if err != nil {
		return nil, err
	}
	if err := applyEnv(cfg, c); err != nil {
		return nil, err
	}
	return cfg, nil
}

func needConfig() (*Config, error) { return needConfigWith(nil) }''')
open('config.go','w').write(s)
c=open('cli.go').read()
c=c.replace("""	if cmd.PreRun != nil {
