open('cli.go','w').write(c)
d=open('cmds.go').read()
d=d.replace("c.PreRun = preRunConfig","c.PreRun = preRunConfigCmd")
open('cmds.go','w').write(d)
PY
cat >> /workspace/config.go <<'GOEOF'

func preRunConfigCmd(c *Command, args []string) error {
	_, err := needConfigWith(c)
