package main

import (
	"encoding/json"
	"fmt"
	"strings"
	"text/template"
)

// jsonSchema is the JSON representation of a schema.
type jsonSchema struct {
	Name   string        `json:"name"`
	Tables []interface{} `json:"tables"`
	Views  []interface{} `json:"views"`
}

// jsonRealm is the JSON representation of a realm.
type jsonRealm struct {
	Schemas []jsonSchema `json:"schemas"`
}

// formatFuncs returns the template functions supported by atlas --format.
func formatFuncs() template.FuncMap {
	return template.FuncMap{
		"json": func(v interface{}) (string, error) {
			b, err := json.Marshal(v)
			if err != nil {
				return "", err
			}
			return string(b), nil
		},
		"sql": func(v interface{}, args ...string) (string, error) {
			return "", nil
		},
		"mermaid": func(v interface{}, args ...string) (string, error) {
			return "", nil
		},
	}
}

// renderFormat renders the given template with the realm data.
func renderFormat(tmpl string, realm jsonRealm) (string, error) {
	t, err := template.New("format").Funcs(formatFuncs()).Parse(tmpl)
	if err != nil {
		return "", fmt.Errorf("parse log format: %v", err)
	}
	var sb strings.Builder
	if err := t.Execute(&sb, realm); err != nil {
		return "", err
	}
	return sb.String(), nil
}
